    @Test
    void dreadInvokeTormentAttributesTheAddedTotalWithoutRerollingDice() throws Exception {
        splendorActor("torment", "Invoke Torment");
        Inbox inbox = new Inbox();
        WebSocket ws = connect(cookie(), inbox);
        try {
            ObjectNode input = MAPPER.createObjectNode().put("type", "roll").put("actorId", "torment")
                    .put("source", "damage").put("expression", "(2d6+3+0)*2");
            var parts = input.putArray("contributions");
            parts.addObject().put("label", "Weapon").put("expression", "(2d6+3)*2");
            parts.addObject().put("label", "Invoke Torment: target has full Stress").put("expression", "(0)*2");
            for (JsonNode part : parts) ((ObjectNode) part).putArray("notes").addObject()
                    .put("label", "Invoke Torment: target has full Stress").put("impact", "Double the rolled damage total");
            ws.sendText(input.toString(), true).join();
            JsonNode roll = inbox.next("roll");
            assertEquals(2, roll.path("rolls").size());
            assertEquals(2, roll.path("breakdown").size());
            int base = roll.path("breakdown").path(0).path("total").asInt();
            assertEquals("Invoke Torment", roll.path("breakdown").path(1).path("label").asText());
            assertEquals(base, roll.path("breakdown").path(1).path("total").asInt());
            assertEquals(base * 2, roll.path("total").asInt());
        } finally { ws.abort(); }
    }

    private ObjectNode splendorActor(String id, String... cards) throws Exception {
        compendiumDir = Path.of("dmmap-daggerheart");
        campaign.getActors().add(Campaign.Actor.builder().id(id).name(id).ownerId(playerId()).build());
        ObjectNode sheet = sageArcanaSheet(cards);
        sheet.withObject("/hp").put("on", 3);
        sheet.withObject("/stress").put("on", 0);
        sheet.withObject("/hope").put("on", 6);
        store.saveSheet(campaign.getId(), id, sheet.toString());
        return sheet;
    }

    private ObjectNode splendorRequest(String actor, String card, String action, JsonNode roll) {
        ObjectNode request = MAPPER.createObjectNode().put("actorId", actor).put("key", "card:" + card).put("actionId", action);
        if (roll != null) request.putObject("roll").put("id", roll.path("id").asLong()).put("ts", roll.path("ts").asLong());
        return request;
    }

    private JsonNode splendorRoll(WebSocket ws, Inbox inbox, String actor, String card, String expression) throws Exception {
        ObjectNode input = MAPPER.createObjectNode().put("type", "roll").put("kind", "duality").put("actorId", actor)
                .put("expression", expression).put("source", "action,spellcast,card:" + card).put("difficulty", 16);
        ws.sendText(input.toString(), true).join();
        return inbox.next("roll");
    }

    @Test
    void splendorHealingHandsUsesActualSuccessAndTargetLongRestLock() throws Exception {
        JsonNode scenario;
        try (var input = getClass().getResourceAsStream("/dmmt/automation/parity/healing-hands.json")) {
            scenario = MAPPER.readTree(input);
        }
        var cast = scenario.required("cast");
        var expected = scenario.required("expected");
        String target = cast.required("target").asText();
        assertEquals(scenario.at("/before/healerStress"), splendorActor("healer", "Healing Hands").at("/stress/on"));
        assertEquals(scenario.at("/before/patientHpMarked"), splendorActor(target).at("/hp/on"));
        String cookie = cookie();
        Inbox inbox = new Inbox();
        WebSocket ws = connect(cookie, inbox);
        try {
            diceSeed(cast.required("seed").asLong());
            JsonNode roll = splendorRoll(ws, inbox, "healer", "Healing Hands", cast.required("roll").asText());
            assertEquals(expected.required("faces"), roll.required("rolls"));
            assertEquals(expected.required("total"), roll.required("total"));
            String choice = cast.required("choice").asText();
            ObjectNode request = splendorRequest("healer", "Healing Hands", choice, roll).put("choiceId", choice)
                    .put("targetActorId", "healer");
            assertEquals(expected.required("selfTargetAllowed").asBoolean() ? 200 : 400, featureHttp(cookie, request).statusCode());
            request.put("targetActorId", target);
            var response = featureHttp(cookie, request);
            assertEquals(200, response.statusCode(), response.body());
            JsonNode patient = MAPPER.readTree(store.loadSheet(campaign.getId(), target));
            assertEquals(expected.required("patientHpMarked"), patient.at("/hp/on"));
            assertEquals(expected.required("expires"), patient.at("/effects/0/until"));
            assertEquals(expected.required("healerStress"), MAPPER.readTree(store.loadSheet(campaign.getId(), "healer")).at("/stress/on"));
            assertTrue(dmMessages.stream().anyMatch(m -> m.path("text").asText().contains(expected.required("reportLine").asText())));
            assertEquals(expected.required("sameRollReusable").asBoolean() ? 200 : 400, featureHttp(cookie, request).statusCode());
            JsonNode second = splendorRoll(ws, inbox, "healer", "Healing Hands", "2d12+30");
            request.set("roll", splendorRequest("healer", "Healing Hands", "hp", second).path("roll"));
            assertEquals(expected.required("newRollBypassesLock").asBoolean() ? 200 : 400, featureHttp(cookie, request).statusCode());
            ObjectNode rested = (ObjectNode) patient.deepCopy();
            rested.put("longRestRevision", 1);
            store.saveSheet(campaign.getId(), "patient", rested.toString());
            ObjectNode saved = rested.deepCopy();
            saved.putArray("effects");
            SplendorActions.preserveSave(saved, (ObjectNode) patient);
            assertTrue(saved.path("effects").isEmpty(), "Only the target's long rest clears the restriction.");
        } finally { ws.abort(); }
    }

    @Test
    void convertedHealingHandsMatchesSharedSuccessfulTargetFixture() throws Exception {
        JsonNode scenario;
        try (var input = getClass().getResourceAsStream("/dmmt/automation/parity/healing-hands.json")) {
            scenario = MAPPER.readTree(input);
        }
        JsonNode cards = MAPPER.readTree(Path.of("dmmap-daggerheart", "domain-cards.json").toFile());
        JsonNode card = null;
        for (JsonNode candidate : cards.path("entries"))
            if ("healing-hands".equals(candidate.path("id").asText())) card = candidate;
        assertNotNull(card);
        ObjectNode legacy = MAPPER.createObjectNode().put("format", "dmmap-daggerheart").put("version", 1)
                .put("category", "domain-cards").put("label", "Fixture");
        legacy.putArray("entries").add(card.deepCopy());
        var converted = dmmt.online.automation.LegacyCatalogConverter.convert(legacy.toString());
        assertEquals(1, converted.converted(), converted.diagnostics().toString());
        automationCompendium();
        java.nio.file.Files.writeString(compendiumDir.resolve("domain-cards.json"), converted.catalog().toString());

        String campaignId = campaign.getId(), target = scenario.requiredAt("/cast/target").asText();
        campaign.getActors().add(Campaign.Actor.builder().id("healer").name("healer").ownerId(playerId()).build());
        campaign.getActors().add(Campaign.Actor.builder().id(target).name(target).ownerId(playerId()).build());
        campaign.getActors().add(Campaign.Actor.builder().id("second").name("second").ownerId(playerId()).build());
        ObjectNode healer = MAPPER.createObjectNode().put("name", "healer").put("level", 2);
        healer.putObject("stress").put("slots", 6).set("on", scenario.requiredAt("/before/healerStress"));
        healer.putObject("hope").put("slots", 6).put("on", 0);
        healer.putArray("traits").addObject().put("name", "Presence").put("mod", 30).put("spellcast", true);
        healer.putArray("loadout").addObject().put("name", card.required("name").asText())
                .put("automationSource", scenario.required("source").asText()).put("instanceId", "healing");
        ObjectNode patient = MAPPER.createObjectNode().put("name", target).put("level", 2);
        patient.putObject("hp").put("slots", 6).set("on", scenario.requiredAt("/before/patientHpMarked"));
        patient.putObject("stress").put("slots", 6).put("on", 3);
        store.saveSheet(campaignId, "healer", healer.toString());
        store.saveSheet(campaignId, target, patient.toString());
        store.saveSheet(campaignId, "second", """
                {"name":"second","level":2,"hp":{"slots":6,"on":3},"stress":{"slots":6,"on":3}}""");
        String owner = cookie();
        Inbox inbox = new Inbox();
        WebSocket socket = connect(owner, inbox);
        try {
            inbox.next("hello");
            var offered = automationHttp(owner, "healer", null);
            assertEquals(200, offered.statusCode(), offered.body());
            JsonNode profile = MAPPER.readTree(offered.body()).requiredAt("/profiles/0");
            assertEquals("spellcast", profile.required("rollKind").asText());
            ObjectNode cast = MAPPER.createObjectNode();
            ObjectNode request = cast.putObject("request").put("requestId", "healing-cast").put("expectedRevision", 0);
            request.putArray("selections");
            request.putObject("profileRoll").put("sourceInstanceId", "healing")
                    .put("profileId", profile.required("id").asText()).put("kind", "spellcast");
            diceSeed(scenario.requiredAt("/cast/seed").asLong());
            var rolled = automationHttp(owner, "healer", cast.toString());
            assertEquals(200, rolled.statusCode(), rolled.body());
            JsonNode roll = MAPPER.readTree(rolled.body()), expected = scenario.required("expected");
            assertEquals(expected.required("total"), roll.requiredAt("/event/check/total"));
            assertEquals("success", roll.requiredAt("/event/check/outcome").asText());
            assertEquals(expected.requiredAt("/faces/0"), roll.requiredAt("/event/check/hopeDie"));
            assertEquals(expected.requiredAt("/faces/1"), roll.requiredAt("/event/check/fearDie"));
            String resultId = roll.requiredAt("/event/resultId").asText();
            var resultOffer = resultHttp(owner, "healer", resultId);
            assertEquals(200, resultOffer.statusCode(), resultOffer.body());
            JsonNode action = null;
            for (JsonNode item : MAPPER.readTree(resultOffer.body()).required("actions"))
                if (scenario.requiredAt("/cast/choice").asText().equals(item.path("ruleId").asText())) action = item;
            assertNotNull(action, resultOffer.body());
            JsonNode targetOption = null, secondOption = null;
            for (JsonNode option : action.requiredAt("/targetSelection/options"))
                if (target.equals(option.path("id").asText())) targetOption = option;
                else if ("second".equals(option.path("id").asText())) secondOption = option;
            assertNotNull(targetOption, action.toString());
            assertNotNull(secondOption, action.toString());

            ObjectNode choose = MAPPER.createObjectNode();
            ObjectNode selection = choose.putObject("request").put("requestId", "healing-hp")
                    .put("expectedRevision", 1).put("resultId", resultId);
            selection.putArray("selections").addObject().put("sourceInstanceId", "healing")
                    .put("ruleId", action.required("ruleId").asText()).put("bindingId", action.required("bindingId").asText());
            selection.putObject("target").put("recipientId", "healer").set("version", targetOption.required("version"));
            assertEquals(expected.required("selfTargetAllowed").asBoolean() ? 200 : 409,
                    automationHttp(owner, "healer", choose.toString()).statusCode());
            ((ObjectNode) selection.required("target")).put("recipientId", target);
            var healed = automationHttp(owner, "healer", choose.toString());
            assertEquals(200, healed.statusCode(), healed.body());
            JsonNode savedHealer = MAPPER.readTree(store.loadSheet(campaignId, "healer"));
            JsonNode savedPatient = MAPPER.readTree(store.loadSheet(campaignId, target));
            assertEquals(expected.required("healerStress"), savedHealer.requiredAt("/stress/on"));
            assertEquals(expected.required("patientHpMarked"), savedPatient.requiredAt("/hp/on"));
            assertEquals(1, savedPatient.requiredAt("/automationState/effects").size());
            assertEquals("rest.long", savedPatient.requiredAt("/automationState/effects/0/until/0").asText());
            assertTrue(store.historyTail(campaignId, 100).stream()
                    .anyMatch(message -> message.path("text").asText().contains(expected.required("reportLine").asText())),
                    healed.body() + " history=" + store.historyTail(campaignId, 100));
            int history = store.historyTail(campaignId, 100).size();
            assertEquals(healed.body(), automationHttp(owner, "healer", choose.toString()).body());
            assertEquals(history, store.historyTail(campaignId, 100).size());
            selection.put("requestId", "duplicate").put("expectedRevision", 2);
            assertEquals(expected.required("sameRollReusable").asBoolean() ? 200 : 409,
                    automationHttp(owner, "healer", choose.toString()).statusCode());
            ((ObjectNode) selection.requiredAt("/selections/0")).put("ruleId", "stress");
            ((ObjectNode) selection.required("target")).put("recipientId", "second").set("version", secondOption.required("version"));
            selection.put("requestId", "alternative");
            assertEquals(409, automationHttp(owner, "healer", choose.toString()).statusCode());
            assertEquals(3, MAPPER.readTree(store.loadSheet(campaignId, "second")).requiredAt("/stress/on").asInt());

            String uri = "http://localhost:" + port + "/api/sheet/" + target;
            JsonNode loaded = MAPPER.readTree(http.send(HttpRequest.newBuilder(URI.create(uri)).header("Cookie", owner)
                    .GET().build(), HttpResponse.BodyHandlers.ofString()).body());
            ObjectNode edited = (ObjectNode) loaded.required("sheet").deepCopy();
            edited.withObject("/automationState").putArray("effects");
            var saved = http.send(HttpRequest.newBuilder(URI.create(uri)).header("Cookie", owner)
                    .header("Content-Type", "application/json").header("If-Match", loaded.required("version").asText())
                    .PUT(HttpRequest.BodyPublishers.ofString(edited.toString())).build(), HttpResponse.BodyHandlers.ofString());
            assertEquals(200, saved.statusCode(), saved.body());
            assertEquals(savedPatient.requiredAt("/automationState/effects"),
                    MAPPER.readTree(store.loadSheet(campaignId, target)).requiredAt("/automationState/effects"));

            request.put("requestId", "healing-again").put("expectedRevision", 2);
            diceSeed(scenario.requiredAt("/cast/seed").asLong());
            var rerolled = automationHttp(owner, "healer", cast.toString());
            assertEquals(200, rerolled.statusCode(), rerolled.body());
            String nextResult = MAPPER.readTree(rerolled.body()).requiredAt("/event/resultId").asText();
            JsonNode nextOffer = MAPPER.readTree(resultHttp(owner, "healer", nextResult).body()).required("actions");
            for (JsonNode next : nextOffer) for (JsonNode option : next.path("targetSelection").path("options"))
                assertNotEquals(target, option.path("id").asText(), next.toString());
            selection.put("requestId", "locked").put("expectedRevision", 3).put("resultId", nextResult);
            ((ObjectNode) selection.requiredAt("/selections/0")).put("ruleId", "hp");
            ((ObjectNode) selection.required("target")).put("recipientId", target).set("version", targetOption.required("version"));
            assertEquals(expected.required("newRollBypassesLock").asBoolean() ? 200 : 409,
                    automationHttp(owner, "healer", choose.toString()).statusCode());
            assertEquals(expected.required("patientHpMarked"), MAPPER.readTree(store.loadSheet(campaignId, target)).requiredAt("/hp/on"));

            var pack = dmmt.online.automation.AutomationHost.compile("fixture",
                    Map.of("domain-cards", converted.catalog().toString()),
                    dmmt.online.automation.LegacyCatalogConverter.coreRecipes());
            var host = dmmt.online.automation.AutomationHost.bundled();
            ObjectNode restedPatient = (ObjectNode) savedPatient.deepCopy();
            assertFalse(host.resetLimits(pack, restedPatient, dmmt.online.automation.AutomationHost.event("rest.short", target, 0)));
            assertEquals(1, restedPatient.requiredAt("/automationState/effects").size());
            assertTrue(host.resetLimits(pack, restedPatient, dmmt.online.automation.AutomationHost.event("rest.long", target, 0)));
            assertTrue(restedPatient.requiredAt("/automationState/effects").isEmpty());
            assertEquals(1, MAPPER.readTree(store.loadSheet(campaignId, target)).requiredAt("/automationState/effects").size());
        } finally { socket.abort(); }
    }

    @Test
    void legacyHealingHandsMatchesSharedOutcomeFixtures() throws Exception {
        JsonNode fixture;
        try (var input = getClass().getResourceAsStream("/dmmt/automation/parity/healing-hands-outcomes.json")) {
            fixture = MAPPER.readTree(input);
        }
        String owner = cookie(), campaignId = campaign.getId();
        Inbox inbox = new Inbox();
        WebSocket socket = connect(owner, inbox);
        try {
            for (JsonNode scenario : fixture.required("scenarios")) {
                String name = scenario.required("name").asText();
                String healerId = "healer-" + name, patientId = "patient-" + name;
                ObjectNode healer = splendorActor(healerId, "Healing Hands");
                ObjectNode patient = splendorActor(patientId);
                campaign.actor(patientId).setName("patient");
                healer.withObject("/stress").set("on", scenario.requiredAt("/before/healerStress"));
                patient.withObject("/hp").set("on", scenario.requiredAt("/before/patientHp"));
                patient.withObject("/stress").set("on", scenario.requiredAt("/before/patientStress"));
                store.saveSheet(campaignId, healerId, healer.toString());
                store.saveSheet(campaignId, patientId, patient.toString());
                JsonNode cast = scenario.required("cast"), expected = scenario.required("expected");
                diceSeed(cast.required("seed").asLong());
                JsonNode roll = splendorRoll(socket, inbox, healerId, "Healing Hands", cast.required("roll").asText());
                assertEquals(expected.required("faces"), roll.required("rolls"), name);
                assertEquals(expected.required("total"), roll.required("total"), name);
                boolean critical = roll.requiredAt("/rolls/0").intValue() == roll.requiredAt("/rolls/1").intValue();
                assertEquals(expected.required("critical").booleanValue(), critical, name);
                assertEquals(expected.required("outcome").asText(),
                        critical || roll.required("total").intValue() >= 13 ? "success" : "failure", name);
                Set<String> choices = new java.util.HashSet<>();
                expected.required("choices").forEach(choice -> choices.add(choice.asText()));
                for (String id : List.of("hp", "stress", "failed-hp", "failed-stress")) {
                    if (choices.contains(id)) continue;
                    ObjectNode unavailable = splendorRequest(healerId, "Healing Hands", id, roll)
                            .put("targetActorId", patientId);
                    assertEquals(400, featureHttp(owner, unavailable).statusCode(), name + ": " + id);
                }
                String choice = cast.required("choice").asText();
                ObjectNode use = splendorRequest(healerId, "Healing Hands", choice, roll).put("targetActorId", patientId);
                var used = featureHttp(owner, use);
                assertEquals(200, used.statusCode(), name + ": " + used.body());
                JsonNode saved = MAPPER.readTree(store.loadSheet(campaignId, patientId));
                assertEquals(expected.required("patientHp"), saved.requiredAt("/hp/on"), name);
                assertEquals(expected.required("patientStress"), saved.requiredAt("/stress/on"), name);
                assertEquals(expected.required("healerStress"),
                        MAPPER.readTree(store.loadSheet(campaignId, healerId)).requiredAt("/stress/on"), name);
                assertTrue(saved.requiredAt("/effects/0/healingHands").booleanValue(), name);
                assertEquals("longRest", saved.requiredAt("/effects/0/until").asText(), name);
                assertTrue(store.historyTail(campaignId, 100).getLast().path("text").asText()
                        .contains(expected.required("reportLine").asText()), name);
                assertEquals(400, featureHttp(owner, use).statusCode(), name);
                String alternative = choices.stream().filter(id -> !id.equals(choice)).findFirst().orElseThrow();
                assertEquals(400, featureHttp(owner, splendorRequest(healerId, "Healing Hands", alternative, roll)
                        .put("targetActorId", patientId)).statusCode(), name);
                assertEquals(saved, MAPPER.readTree(store.loadSheet(campaignId, patientId)), name);
            }
        } finally { socket.abort(); }
    }

    @Test
    void convertedHealingHandsMatchesSharedOutcomeFixtures() throws Exception {
        JsonNode fixture;
        try (var input = getClass().getResourceAsStream("/dmmt/automation/parity/healing-hands-outcomes.json")) {
            fixture = MAPPER.readTree(input);
        }
        JsonNode cards = MAPPER.readTree(Path.of("dmmap-daggerheart", "domain-cards.json").toFile());
        JsonNode card = null;
        for (JsonNode candidate : cards.path("entries"))
            if ("healing-hands".equals(candidate.path("id").asText())) card = candidate;
        assertNotNull(card);
        ObjectNode legacy = MAPPER.createObjectNode().put("format", "dmmap-daggerheart").put("version", 1)
                .put("category", "domain-cards").put("label", "Fixture");
        legacy.putArray("entries").add(card.deepCopy());
        var converted = dmmt.online.automation.LegacyCatalogConverter.convert(legacy.toString());
        assertEquals(1, converted.converted(), converted.diagnostics().toString());
        automationCompendium();
        java.nio.file.Files.writeString(compendiumDir.resolve("domain-cards.json"), converted.catalog().toString());
        String owner = cookie(), campaignId = campaign.getId();
        Inbox inbox = new Inbox();
        WebSocket socket = connect(owner, inbox);
        try {
            inbox.next("hello");
            for (JsonNode scenario : fixture.required("scenarios")) {
                String name = scenario.required("name").asText();
                String healerId = "healer-" + name, patientId = "patient-" + name;
                campaign.getActors().add(Campaign.Actor.builder().id(healerId).name("healer").ownerId(playerId()).build());
                campaign.getActors().add(Campaign.Actor.builder().id(patientId).name("patient").ownerId(playerId()).build());
                ObjectNode healer = MAPPER.createObjectNode().put("name", "healer").put("level", 2);
                healer.putObject("stress").put("slots", 6).set("on", scenario.requiredAt("/before/healerStress"));
                healer.putObject("hope").put("slots", 6).put("on", 0);
                healer.putArray("traits").addObject().put("name", "Presence")
                        .set("mod", scenario.requiredAt("/cast/trait"));
                ((ObjectNode) healer.requiredAt("/traits/0")).put("spellcast", true);
                healer.putArray("loadout").addObject().put("name", "Healing Hands")
                        .put("automationSource", fixture.required("source").asText()).put("instanceId", "healing");
                ObjectNode patient = MAPPER.createObjectNode().put("name", "patient").put("level", 2);
                patient.putObject("hp").put("slots", 6).set("on", scenario.requiredAt("/before/patientHp"));
                patient.putObject("stress").put("slots", 6).set("on", scenario.requiredAt("/before/patientStress"));
                store.saveSheet(campaignId, healerId, healer.toString());
                store.saveSheet(campaignId, patientId, patient.toString());
                JsonNode profile = MAPPER.readTree(automationHttp(owner, healerId, null).body()).requiredAt("/profiles/0");
                ObjectNode cast = MAPPER.createObjectNode();
                ObjectNode request = cast.putObject("request").put("requestId", "cast").put("expectedRevision", 0);
                request.putArray("selections");
                request.putObject("profileRoll").put("sourceInstanceId", "healing")
                        .put("profileId", profile.required("id").asText()).put("kind", "spellcast");
                diceSeed(scenario.requiredAt("/cast/seed").asLong());
                var rolled = automationHttp(owner, healerId, cast.toString());
                assertEquals(200, rolled.statusCode(), name + ": " + rolled.body());
                JsonNode receipt = MAPPER.readTree(rolled.body()), expected = scenario.required("expected");
                assertEquals(expected.requiredAt("/faces/0"), receipt.requiredAt("/event/check/hopeDie"), name);
                assertEquals(expected.requiredAt("/faces/1"), receipt.requiredAt("/event/check/fearDie"), name);
                assertEquals(expected.required("total"), receipt.requiredAt("/event/check/total"), name);
                assertEquals(expected.required("critical"), receipt.requiredAt("/event/check/critical"), name);
                assertEquals(expected.required("outcome"), receipt.requiredAt("/event/check/outcome"), name);
                String resultId = receipt.requiredAt("/event/resultId").asText();
                JsonNode actions = MAPPER.readTree(resultHttp(owner, healerId, resultId).body()).required("actions");
                Set<String> choices = new java.util.HashSet<>();
                expected.required("choices").forEach(choice -> choices.add(choice.asText()));
                assertEquals(choices, Set.copyOf(actions.findValuesAsText("ruleId")), name);
                String choice = scenario.requiredAt("/cast/choice").asText();
                JsonNode action = null;
                for (JsonNode candidate : actions)
                    if (choice.equals(candidate.required("ruleId").asText())) action = candidate;
                assertNotNull(action, name);
                JsonNode target = null;
                for (JsonNode candidate : action.requiredAt("/targetSelection/options"))
                    if (patientId.equals(candidate.required("id").asText())) target = candidate;
                assertNotNull(target, name);
                ObjectNode use = MAPPER.createObjectNode();
                ObjectNode selection = use.putObject("request").put("requestId", "use").put("expectedRevision", 1)
                        .put("resultId", resultId);
                selection.putArray("selections").addObject().put("sourceInstanceId", "healing")
                        .put("ruleId", choice).put("bindingId", action.required("bindingId").asText());
                selection.putObject("target").put("recipientId", patientId).set("version", target.required("version"));
                var used = automationHttp(owner, healerId, use.toString());
                assertEquals(200, used.statusCode(), name + ": " + used.body());
                JsonNode saved = MAPPER.readTree(store.loadSheet(campaignId, patientId));
                assertEquals(expected.required("patientHp"), saved.requiredAt("/hp/on"), name);
                assertEquals(expected.required("patientStress"), saved.requiredAt("/stress/on"), name);
                assertEquals(expected.required("healerStress"),
                        MAPPER.readTree(store.loadSheet(campaignId, healerId)).requiredAt("/stress/on"), name);
                assertEquals("rest.long", saved.requiredAt("/automationState/effects/0/until/0").asText(), name);
                assertTrue(store.historyTail(campaignId, 100).getLast().path("text").asText()
                        .contains(expected.required("reportLine").asText()), name);
                int history = store.historyTail(campaignId, 100).size();
                assertEquals(used.body(), automationHttp(owner, healerId, use.toString()).body(), name);
                assertEquals(history, store.historyTail(campaignId, 100).size(), name);
                selection.put("requestId", "duplicate").put("expectedRevision", 2);
                assertEquals(409, automationHttp(owner, healerId, use.toString()).statusCode(), name);
                String alternative = choices.stream().filter(id -> !id.equals(choice)).findFirst().orElseThrow();
                ((ObjectNode) selection.requiredAt("/selections/0")).put("ruleId", alternative);
                selection.put("requestId", "alternative");
                assertEquals(409, automationHttp(owner, healerId, use.toString()).statusCode(), name);
                assertEquals(saved, MAPPER.readTree(store.loadSheet(campaignId, patientId)), name);
            }
        } finally { socket.abort(); }
    }

