    private static ObjectNode recoveryRollRequest(JsonNode description, String requestId) {
        ObjectNode body = MAPPER.createObjectNode();
        ObjectNode request = body.putObject("request").put("requestId", requestId)
                .put("expectedRevision", description.path("revision").asLong())
                .put("expectedHolderRevision", description.path("holderRevision").asLong())
                .put("expectedOfferRevision", description.path("offerRevision").asLong());
        request.set("selection", restSelection(description.path("actions").get(0)));
        return body;
    }

    private static long seedForDie(int sides, int face) {
        for (long seed = 0; seed < 100000; seed++)
            if (new java.util.Random(seed).nextInt(sides) + 1 == face) return seed;
        throw new AssertionError("No seed found for d" + sides + " = " + face);
    }

    private static long seedForDice(int[] sides, int[] faces) {
        for (long seed = 0; seed < 100000; seed++) {
            var random = new java.util.Random(seed);
            boolean match = true;
            for (int i = 0; i < sides.length; i++) match &= random.nextInt(sides[i]) + 1 == faces[i];
            if (match) return seed;
        }
        throw new AssertionError("No seed found for the dice.");
    }

    private static ObjectNode claimRequest(JsonNode description, String recipientId, String requestId) {
        ObjectNode body = MAPPER.createObjectNode();
        ObjectNode request = body.putObject("request").put("requestId", requestId).put("recipientId", recipientId)
                .put("expectedRevision", description.path("revision").asLong())
                .put("expectedRecipientRevision", description.path("recipientRevision").asLong())
                .put("expectedClaimRevision", description.path("claimRevision").asLong());
        request.set("selection", restSelection(description.path("actions").get(0)));
        return body;
    }

    private static ObjectNode restSelection(JsonNode descriptor) {
        ObjectNode selection = MAPPER.createObjectNode()
                .put("sourceInstanceId", descriptor.path("sourceInstanceId").asText())
                .put("ruleId", descriptor.path("ruleId").asText())
                .put("bindingId", descriptor.path("bindingId").asText());
        selection.putObject("inputs");
        return selection;
    }

    private static JsonNode restDescriptor(JsonNode choices, String rule) {
        for (JsonNode choice : choices) if (rule.equals(choice.path("ruleId").asText())) return choice;
        throw new AssertionError("Missing rest rule " + rule + " in " + choices);
    }

    private static ObjectNode restRequest(JsonNode offer, String requestId) {
        ObjectNode body = MAPPER.createObjectNode();
        ObjectNode request = body.putObject("request").put("requestId", requestId)
                .put("offerVersion", offer.path("offerVersion").asText()).put("kind", offer.path("kind").asText())
                .put("expectedRevision", offer.path("revision").asLong());
        request.putArray("preparation");
        request.putArray("moves");
        request.putArray("completion");
        return body;
    }

    private static ObjectNode addRestMove(ObjectNode request, JsonNode descriptor) {
        ObjectNode move = request.withArray("moves").addObject();
        move.set("selection", restSelection(descriptor));
        move.putArray("options");
        return move;
    }

