    @Test
    void formatTwoRestOffersAndCommitsOwnerChoicesOnce() throws Exception {
        installRestRules();
        campaign.getActors().add(Campaign.Actor.builder().id("resting").name("Ada").ownerId(playerId()).build());
        String original = """
                {"name":"Ada","level":2,"hp":{"slots":6,"total":6,"on":5},
                 "stress":{"slots":6,"total":6,"on":5},"armorTrack":{"slots":4,"total":4,"on":2},
                 "hope":{"slots":6,"total":6,"on":1},"features":[],"inventory":[]}
                """;
        store.saveSheet(campaign.getId(), "resting", original);
        String before = store.loadSheet(campaign.getId(), "resting");
        String owner = cookie(), other = allyCookie("rest-viewer");
        assertEquals(403, restHttp(other, "resting", "short", null).statusCode());
        var old = http.send(HttpRequest.newBuilder(URI.create("http://localhost:" + port + "/api/automation/0/resting/rest?kind=short"))
                .header("Cookie", owner).GET().build(), HttpResponse.BodyHandlers.ofString());
        assertEquals(409, old.statusCode());
        assertEquals("automationCompatibilityMismatch", MAPPER.readTree(old.body()).path("code").asText());
        diceSeed(13);
        var described = restHttp(owner, "resting", "short", null);
        assertEquals(200, described.statusCode(), described.body());
        JsonNode offer = MAPPER.readTree(described.body());
        assertEquals(2, offer.at("/plan/moves").asInt());
        assertTrue(restDescriptor(offer.path("preparation"), "test-extra").path("available").asBoolean());
        assertTrue(restDescriptor(offer.path("completion"), "test-benefit").path("available").asBoolean());
        JsonNode tend = restDescriptor(offer.path("moves"), "rest-tend");
        JsonNode care = restDescriptor(tend.path("options"), "test-care");
        assertTrue(care.path("available").asBoolean());
        assertFalse(restDescriptor(restDescriptor(offer.path("moves"), "rest-stress").path("options"), "test-care")
                .path("available").asBoolean());
        assertEquals(before, store.loadSheet(campaign.getId(), "resting"), "Describing does not save or sample.");
        JsonNode staleLong = MAPPER.readTree(restHttp(owner, "resting", "long", null).body());
        ObjectNode body = restRequest(offer, "rest-1");
        ObjectNode request = (ObjectNode) body.path("request");
        request.withArray("preparation").add(restSelection(restDescriptor(offer.path("preparation"), "test-extra")));
        ObjectNode first = addRestMove(request, tend);
        first.withArray("options").add(restSelection(care));
        addRestMove(request, restDescriptor(offer.path("moves"), "rest-prepare"));
        addRestMove(request, restDescriptor(offer.path("moves"), "rest-stress"));
        request.withArray("completion").add(restSelection(restDescriptor(offer.path("completion"), "test-benefit")));
        assertEquals(403, restHttp(other, "resting", null, body.toString()).statusCode());
        ObjectNode targeted = body.deepCopy();
        ((ObjectNode) targeted.at("/request/moves/0")).putObject("target").put("recipientId", "forged");
        assertEquals(400, restHttp(owner, "resting", null, targeted.toString()).statusCode());
        assertEquals(before, store.loadSheet(campaign.getId(), "resting"));

        var executed = restHttp(owner, "resting", null, body.toString());
        assertEquals(200, executed.statusCode(), executed.body());
        JsonNode receipt = MAPPER.readTree(executed.body());
        assertEquals(3, receipt.at("/progress/moves").asInt());
        assertEquals(3, receipt.at("/progress/slotsUsed").asInt());
        int firstFace = new java.util.Random(13).nextInt(4) + 1;
        assertEquals(firstFace, receipt.at("/actions/2/diceRolls/0/faces/0").asInt(), receipt.toString());
        JsonNode saved = MAPPER.readTree(store.loadSheet(campaign.getId(), "resting"));
        assertEquals(Math.max(0, 5 - firstFace - 2 - 1), saved.at("/hp/on").asInt());
        assertEquals(3, saved.at("/hope/on").asInt());
        assertEquals(1, saved.path("shortRestsInRow").asInt());
        assertEquals(1, saved.at("/automationState/revision").asInt());
        int history = store.historyTail(campaign.getId(), 100).size();
        assertTrue(history >= 4, "Rest reports are published with the transaction.");
        String after = store.loadSheet(campaign.getId(), "resting");
        assertEquals(executed.body(), restHttp(owner, "resting", null, body.toString()).body());
        assertEquals(after, store.loadSheet(campaign.getId(), "resting"));
        assertEquals(history, store.historyTail(campaign.getId(), 100).size());
        ObjectNode reused = body.deepCopy();
        ((ArrayNode) reused.at("/request/completion")).removeAll();
        assertEquals(409, restHttp(owner, "resting", null, reused.toString()).statusCode());
        assertEquals(409, restHttp(owner, "resting", null, restRequest(staleLong, "stale").toString()).statusCode());
        assertEquals(after, store.loadSheet(campaign.getId(), "resting"));

        var longOffer = restHttp(owner, "resting", "long", null);
        assertEquals(200, longOffer.statusCode(), longOffer.body());
        JsonNode longRest = MAPPER.readTree(longOffer.body());
        ObjectNode longBody = restRequest(longRest, "rest-2");
        addRestMove((ObjectNode) longBody.path("request"), restDescriptor(longRest.path("moves"), "rest-stress-all"));
        var completed = restHttp(owner, "resting", null, longBody.toString());
        assertEquals(200, completed.statusCode(), completed.body());
        JsonNode afterLong = MAPPER.readTree(store.loadSheet(campaign.getId(), "resting"));
        assertEquals(0, afterLong.at("/stress/on").asInt());
        assertEquals(0, afterLong.path("shortRestsInRow").asInt());
        assertEquals(1, afterLong.path("longRestRevision").asInt());
        assertEquals(2, afterLong.at("/automationState/revision").asInt());
    }

    @Test
    void formatTwoRestsReturnAndRecoverCompanionsInTheSavedSheet() throws Exception {
        installRestRules();
        var converted = dmmt.online.automation.LegacyCatalogConverter.convert("""
                {"format":"dmmap-daggerheart","version":1,"category":"domain-cards","entries":[
                 {"id":"pet","name":"Companion","automation":{"companion":{
                   "evasion":10,"stress":3,"maxStress":6,"options":[]}}}]}
                """);
        assertEquals(1, converted.converted(), converted.diagnostics().toString());
        java.nio.file.Files.writeString(compendiumDir.resolve("domain-cards.json"), converted.catalog().toString());
        campaign.getActors().add(Campaign.Actor.builder().id("resting").name("Ada").ownerId(playerId()).build());
        store.saveSheet(campaign.getId(), "resting", """
                {"name":"Ada","level":1,"hp":{"slots":6,"on":1},"stress":{"slots":6,"on":5},
                 "armorTrack":{"slots":3,"on":0},"hope":{"slots":6,"on":1},
                 "companion":{"name":"Fox","stress":{"slots":5,"on":5},"unavailable":true},
                 "loadout":[{"name":"Companion","instanceId":"pet","automationSource":"domain-cards:pet"}],
                 "automationState":{"pools":{"companion-stress-slots":{"max":6,"value":6}}}}
                """);
        String owner = cookie();
        diceSeed(13);
        JsonNode shortOffer = MAPPER.readTree(restHttp(owner, "resting", "short", null).body());
        ObjectNode shortBody = restRequest(shortOffer, "companion-short");
        addRestMove((ObjectNode) shortBody.path("request"), restDescriptor(shortOffer.path("moves"), "rest-stress"));
        var shortResult = restHttp(owner, "resting", null, shortBody.toString());
        assertEquals(200, shortResult.statusCode(), shortResult.body());
        JsonNode afterShort = MAPPER.readTree(store.loadSheet(campaign.getId(), "resting"));
        assertTrue(afterShort.at("/companion/unavailable").asBoolean());
        assertEquals(5, afterShort.at("/companion/stress/on").asInt());
        assertEquals(5, afterShort.at("/automationState/pools/companion-stress-slots/max").asInt());

        JsonNode longOffer = MAPPER.readTree(restHttp(owner, "resting", "long", null).body());
        ObjectNode longBody = restRequest(longOffer, "companion-long");
        addRestMove((ObjectNode) longBody.path("request"), restDescriptor(longOffer.path("moves"), "rest-stress-all"));
        var completed = restHttp(owner, "resting", null, longBody.toString());
        assertEquals(200, completed.statusCode(), completed.body());
        JsonNode receipt = MAPPER.readTree(completed.body());
        var rules = receipt.path("actions").findValuesAsText("ruleId");
        assertTrue(rules.indexOf("companion-returns") < rules.indexOf("rest-stress-all"), rules.toString());
        assertTrue(rules.indexOf("rest-stress-all") < rules.indexOf("companion-recovers"), rules.toString());
        JsonNode saved = MAPPER.readTree(store.loadSheet(campaign.getId(), "resting"));
        assertFalse(saved.at("/companion/unavailable").asBoolean());
        int companionStress = Math.max(0, 4 - afterShort.at("/stress/on").asInt());
        assertEquals(companionStress, saved.at("/companion/stress/on").asInt());
        assertEquals(5 - companionStress, saved.at("/automationState/pools/companion-stress-slots/value").asInt());
        String after = store.loadSheet(campaign.getId(), "resting");
        int history = store.historyTail(campaign.getId(), 100).size();
        assertEquals(completed.body(), restHttp(owner, "resting", null, longBody.toString()).body());
        assertEquals(after, store.loadSheet(campaign.getId(), "resting"));
        assertEquals(history, store.historyTail(campaign.getId(), 100).size());
    }

    @Test
    void formatTwoRestPublishesIndependentCardOffersAndClaimsThemAtomically() throws Exception {
        installRestRules();
        var converted = dmmt.online.automation.LegacyCatalogConverter.convert("""
                {"format":"dmmap-daggerheart","version":1,"category":"domain-cards","label":"Rest cards","entries":[
                 {"id":"kindness","name":"Kindness","automation":{"rest":{"passives":[
                  {"id":"share","label":"Share Hope","chooseAlly":true,
                   "steps":[{"op":"gain","resource":"hope","amount":1}]}]}}},
                 {"id":"comfort","name":"Comfort","automation":{"rest":{"passives":[
                  {"id":"share","label":"Share Comfort","chooseAlly":true,
                   "steps":[{"op":"clear","resource":"stress","amount":1}]}]}}}]}
                """);
        assertEquals(2, converted.converted(), converted.diagnostics().toString());
        java.nio.file.Files.writeString(compendiumDir.resolve("domain-cards.json"), converted.catalog().toString());
        String owner = cookie(), mira = allyCookie("mira-player"), borin = allyCookie("borin-player");
        campaign.getActors().add(Campaign.Actor.builder().id("resting").name("Ada").ownerId(playerId()).build());
        campaign.getActors().add(Campaign.Actor.builder().id("own-alt").name("Alt").ownerId(playerId()).build());
        campaign.getActors().add(Campaign.Actor.builder().id("mira").name("Mira").ownerId("mira-player").build());
        campaign.getActors().add(Campaign.Actor.builder().id("borin").name("Borin").ownerId("borin-player").build());
        ObjectNode source = (ObjectNode) MAPPER.readTree("""
                {"name":"Ada","level":1,"hp":{"slots":6,"on":2},"stress":{"slots":6,"on":1},
                 "armorTrack":{"slots":3,"on":0},"hope":{"slots":6,"on":1},"loadout":[
                  {"name":"Kindness","automationSource":"domain-cards:kindness","instanceId":"card-a"},
                  {"name":"Comfort","automationSource":"domain-cards:comfort","instanceId":"card-b"}]}
                """);
        store.saveSheet(campaign.getId(), "resting", source.toString());
        for (String id : List.of("own-alt", "mira", "borin"))
            store.saveSheet(campaign.getId(), id, """
                    {"name":"%s","level":1,"hp":{"slots":6,"on":2},"stress":{"slots":6,"on":3},
                     "armorTrack":{"slots":3,"on":0},"hope":{"slots":6,"on":1}}
                    """.formatted(id));
        JsonNode rest = MAPPER.readTree(restHttp(owner, "resting", "short", null).body());
        ObjectNode restBody = restRequest(rest, "card-rest");
        ArrayNode completion = restBody.withObject("/request").withArray("completion");
        for (JsonNode option : rest.path("completion")) {
            if ("share".equals(option.path("ruleId").asText())) completion.add(restSelection(option));
        }
        assertEquals(2, completion.size(), rest.toString());
        var completed = restHttp(owner, "resting", null, restBody.toString());
        assertEquals(200, completed.statusCode(), completed.body());
        Map<String, JsonNode> offers = new java.util.HashMap<>();
        for (JsonNode message : store.historyTail(campaign.getId(), 100))
            if (message.path("automationClaim").isObject())
                offers.put(message.at("/automationClaim/sourceInstanceId").asText(), message);
        assertEquals(Set.of("card-a", "card-b"), offers.keySet());
        JsonNode hopeOffer = offers.get("card-a"), stressOffer = offers.get("card-b");
        assertEquals("share-ally", hopeOffer.at("/automationClaim/group").asText());
        assertEquals(1, hopeOffer.at("/automationClaim/limit").asInt());
        assertTrue(OnlineSessionServer.playerView(hopeOffer).at("/automationClaim/originEvent").isMissingNode());
        assertTrue(OnlineSessionServer.playerView(hopeOffer).at("/automationClaim/receipts").isMissingNode());
        assertTrue(MAPPER.readTree(claimHttp(owner, hopeOffer, "own-alt", null).body()).path("actions").isEmpty());
        assertEquals(403, claimHttp(owner, hopeOffer, "mira", null).statusCode());
        var badVersion = http.send(HttpRequest.newBuilder(URI.create("http://localhost:" + port
                        + "/api/automation/0/resting/claims/" + hopeOffer.path("id").asLong() + "/"
                        + hopeOffer.path("ts").asLong() + "?recipientId=mira"))
                .header("Cookie", mira).GET().build(), HttpResponse.BodyHandlers.ofString());
        assertEquals(409, badVersion.statusCode());

        JsonNode described = MAPPER.readTree(claimHttp(mira, hopeOffer, "mira", null).body());
        assertEquals("card-a", described.at("/actions/0/sourceInstanceId").asText(), described.toString());
        ObjectNode request = claimRequest(described, "mira", "hope-claim");
        ObjectNode forged = request.deepCopy();
        ((ObjectNode) forged.at("/request/selection")).put("sourceInstanceId", "card-b");
        String beforeSource = store.loadSheet(campaign.getId(), "resting");
        String beforeMira = store.loadSheet(campaign.getId(), "mira");
        assertEquals(400, claimHttp(mira, hopeOffer, "mira", forged.toString()).statusCode());
        ObjectNode stale = request.deepCopy();
        ((ObjectNode) stale.path("request")).put("expectedClaimRevision", 1);
        assertEquals(409, claimHttp(mira, hopeOffer, "mira", stale.toString()).statusCode());
        assertEquals(beforeSource, store.loadSheet(campaign.getId(), "resting"));
        assertEquals(beforeMira, store.loadSheet(campaign.getId(), "mira"));

        var accepted = claimHttp(mira, hopeOffer, "mira", request.toString());
        assertEquals(200, accepted.statusCode(), accepted.body());
        assertEquals(2, MAPPER.readTree(store.loadSheet(campaign.getId(), "mira")).at("/hope/on").asInt());
        int history = store.historyTail(campaign.getId(), 100).size();
        assertEquals(accepted.body(), claimHttp(mira, hopeOffer, "mira", request.toString()).body());
        assertEquals(history, store.historyTail(campaign.getId(), 100).size());
        assertEquals(409, claimHttp(borin, hopeOffer, "borin", request.toString()).statusCode());
        assertTrue(MAPPER.readTree(claimHttp(borin, hopeOffer, "borin", null).body()).path("actions").isEmpty());

        JsonNode comfort = MAPPER.readTree(claimHttp(borin, stressOffer, "borin", null).body());
        assertEquals("card-b", comfort.at("/actions/0/sourceInstanceId").asText(), comfort.toString());
        var comfortAccepted = claimHttp(borin, stressOffer, "borin",
                claimRequest(comfort, "borin", "stress-claim").toString());
        assertEquals(200, comfortAccepted.statusCode(), comfortAccepted.body());
        assertEquals(2, MAPPER.readTree(store.loadSheet(campaign.getId(), "borin")).at("/stress/on").asInt());
        assertEquals(accepted.body(), claimHttp(mira, hopeOffer, "mira", request.toString()).body());
    }

    @Test
    void formatTwoRestSelfClaimUsesTheActualRestOutcomeAndOneSheet() throws Exception {
        installRestRules();
        Path file = compendiumDir.resolve("rules").resolve("ruleset.json");
        ObjectNode ruleset = (ObjectNode) MAPPER.readTree(file.toFile());
        ruleset.withObject("/automation").withArray("rules").addAll((ArrayNode) MAPPER.readTree("""
                [
                 {"id":"self-offer","bindings":[{"id":"rest","event":"rest.short","surface":"rest","mode":"option"}],
                  "do":[{"op":"claim.offer","group":"rest-gift","label":"Choose a gift","limit":1}],
                  "ui":{"label":"Offer gift"}},
                 {"id":"self-gift","bindings":[{"id":"claim","event":"claim.accept","surface":"chat","mode":"button",
                    "claimGroup":"rest-gift","audience":"self","claimScope":{"recipients":"sourceActor"}}],
                  "when":{"gt":[{"read":"event.rest.cleared.stress"},0]},
                  "do":[{"op":"resource.gain","pool":"recipient.hope","amount":1},
                        {"op":"inventory.grant","catalog":"consumables","entry":"minor-health-potion",
                         "quantity":1,"to":"recipient","label":"A potion"}],
                  "ui":{"label":"Gain Hope","report":"{recipient.name} gained Hope."}}
                ]
                """));
        java.nio.file.Files.writeString(file, ruleset.toString());
        String owner = cookie(), other = allyCookie("claim-viewer");
        campaign.getActors().add(Campaign.Actor.builder().id("resting").name("Ada").ownerId(playerId()).build());
        store.saveSheet(campaign.getId(), "resting", """
                {"name":"Ada","level":1,"hp":{"slots":6,"on":2},"stress":{"slots":6,"on":3},
                 "armorTrack":{"slots":3,"on":0},"hope":{"slots":6,"on":1}}
                """);
        JsonNode rest = MAPPER.readTree(restHttp(owner, "resting", "short", null).body());
        ObjectNode body = restRequest(rest, "self-rest");
        addRestMove((ObjectNode) body.path("request"), restDescriptor(rest.path("moves"), "rest-stress"));
        body.withObject("/request").withArray("completion")
                .add(restSelection(restDescriptor(rest.path("completion"), "self-offer")));
        var completed = restHttp(owner, "resting", null, body.toString());
        assertEquals(200, completed.statusCode(), completed.body());
        JsonNode offer = null;
        for (JsonNode message : store.historyTail(campaign.getId(), 100))
            if (message.path("automationClaim").isObject()) offer = message;
        assertNotNull(offer);
        assertEquals(403, claimHttp(other, offer, "resting", null).statusCode());
        var described = claimHttp(owner, offer, "resting", null);
        assertEquals(200, described.statusCode(), described.body());
        JsonNode choices = MAPPER.readTree(described.body());
        assertTrue(choices.at("/actions/0/available").asBoolean(), choices.toString());
        ObjectNode claim = claimRequest(choices, "resting", "self-claim");
        var accepted = claimHttp(owner, offer, "resting", claim.toString());
        assertEquals(200, accepted.statusCode(), accepted.body());
        JsonNode saved = MAPPER.readTree(store.loadSheet(campaign.getId(), "resting"));
        assertEquals(2, saved.at("/hope/on").asInt());
        assertEquals(2, saved.at("/automationState/revision").asInt());
        assertEquals("Minor Health Potion", saved.at("/inventory/0/name").asText());
        assertEquals(1, saved.at("/inventory/0/qty").asInt());
        assertEquals(accepted.body(), claimHttp(owner, offer, "resting", claim.toString()).body());
    }

    @Test
    void targetedRestLetsOnlyTheRecipientRestoreOneSpentFeatureUse() throws Exception {
        installRestRules();
        Path file = compendiumDir.resolve("rules").resolve("ruleset.json");
        ObjectNode ruleset = (ObjectNode) MAPPER.readTree(file.toFile());
        ruleset.withObject("/automation").withArray("rules").add(MAPPER.readTree("""
                {"id":"give-use","bindings":[{"id":"move","event":"downtime.move","surface":"downtime","mode":"button",
                  "restMove":{"id":"give-use","kind":"any","ally":true},
                  "targetSelection":{"cardinality":"one","scope":"activeCharacters","excludeSource":true}}],
                 "do":[{"op":"limit.restore","to":"recipient","label":"Choose a feature to restore"}],
                 "ui":{"label":"Restore an ally's feature"}}
                """));
        java.nio.file.Files.writeString(file, ruleset.toString());
        String owner = cookie(), mira = allyCookie("mira-player");
        campaign.getActors().add(Campaign.Actor.builder().id("resting").name("Ada").ownerId(playerId()).build());
        campaign.getActors().add(Campaign.Actor.builder().id("mira").name("Mira").ownerId("mira-player").build());
        campaign.getActors().add(Campaign.Actor.builder().id("mira-alt").name("Alt").ownerId("mira-player").build());
        store.saveSheet(campaign.getId(), "resting", """
                {"name":"Ada","level":1,"hp":{"slots":6,"on":2},"stress":{"slots":6,"on":1},
                 "armorTrack":{"slots":3,"on":0},"hope":{"slots":6,"on":1}}
                """);
        store.saveSheet(campaign.getId(), "mira", """
                {"name":"Mira","level":1,"hp":{"slots":6,"on":2},"stress":{"slots":6,"on":1},
                 "armorTrack":{"slots":3,"on":0},"hope":{"slots":6,"on":1},
                 "features":[
                  {"name":"First Rally","automationSource":"classes:tester:features:rally","instanceId":"r1"},
                  {"name":"Second Rally","automationSource":"classes:tester:features:rally","instanceId":"r2"},
                  {"name":"Unused Rally","automationSource":"classes:tester:features:rally","instanceId":"r3"}],
                 "automationState":{"revision":4,"sources":{"r1":{"usage":{"once":1}},
                   "r2":{"usage":{"once":1}},"r3":{"usage":{"once":0}}}}}
                """);
        store.saveSheet(campaign.getId(), "mira-alt", """
                {"name":"Alt","level":1,"hp":{"slots":6,"on":0},"stress":{"slots":6,"on":0},
                 "armorTrack":{"slots":3,"on":0},"hope":{"slots":6,"on":0}}
                """);
        JsonNode rest = MAPPER.readTree(restHttp(owner, "resting", "short", null).body());
        ObjectNode restBody = restRequest(rest, "restore-rest");
        targetRestMove(restBody, rest, "give-use", "mira");
        var completed = restHttp(owner, "resting", null, restBody.toString());
        assertEquals(200, completed.statusCode(), completed.body());
        JsonNode offer = store.historyTail(campaign.getId(), 100).stream()
                .filter(message -> "limit.restore".equals(message.at("/automationClaim/kind").asText()))
                .findFirst().orElseThrow();
        assertEquals("mira", OnlineSessionServer.playerView(offer).at("/automationClaim/recipientActorId").asText());
        assertEquals(403, claimHttp(owner, offer, "mira", null).statusCode());
        var otherDescription = claimHttp(mira, offer, "mira-alt", null);
        assertEquals(200, otherDescription.statusCode(), otherDescription.body());
        assertTrue(MAPPER.readTree(otherDescription.body()).path("actions").isEmpty());
        var described = claimHttp(mira, offer, "mira", null);
        assertEquals(200, described.statusCode(), described.body());
        JsonNode choices = MAPPER.readTree(described.body());
        JsonNode options = choices.at("/actions/0/inputs/0/options");
        assertEquals(List.of("2:r1:once", "2:r2:once"), options.findValuesAsText("id"));
        ObjectNode request = claimRequest(choices, "mira", "restore-choice");
        ((ObjectNode) request.at("/request/selection/inputs")).put("limit", "2:r2:once");
        String originalSource = store.loadSheet(campaign.getId(), "resting");
        String originalRecipient = store.loadSheet(campaign.getId(), "mira");
        ObjectNode forged = request.deepCopy();
        ((ObjectNode) forged.at("/request/selection/inputs")).put("limit", "2:r3:once");
        assertEquals(409, claimHttp(mira, offer, "mira", forged.toString()).statusCode());
        ObjectNode otherTarget = request.deepCopy();
        ((ObjectNode) otherTarget.path("request")).put("recipientId", "mira-alt");
        assertEquals(403, claimHttp(mira, offer, "mira-alt", otherTarget.toString()).statusCode());
        ObjectNode stale = request.deepCopy();
        ((ObjectNode) stale.path("request")).put("expectedClaimRevision", 1);
        assertEquals(409, claimHttp(mira, offer, "mira", stale.toString()).statusCode());
        assertEquals(originalSource, store.loadSheet(campaign.getId(), "resting"));
        assertEquals(originalRecipient, store.loadSheet(campaign.getId(), "mira"));
        var accepted = claimHttp(mira, offer, "mira", request.toString());
        assertEquals(200, accepted.statusCode(), accepted.body());
        JsonNode saved = MAPPER.readTree(store.loadSheet(campaign.getId(), "mira"));
        assertEquals(1, saved.at("/automationState/sources/r1/usage/once").asInt());
        assertEquals(0, saved.at("/automationState/sources/r2/usage/once").asInt());
        assertEquals(originalSource, store.loadSheet(campaign.getId(), "resting"));
        assertTrue(MAPPER.readTree(accepted.body()).at("/actions/0/report").asText().contains("Second Rally"));
        int history = store.historyTail(campaign.getId(), 100).size();
        assertEquals(accepted.body(), claimHttp(mira, offer, "mira", request.toString()).body());
        assertEquals(history, store.historyTail(campaign.getId(), 100).size());
        assertTrue(MAPPER.readTree(claimHttp(mira, offer, "mira", null).body()).path("actions").isEmpty());
        ObjectNode duplicate = request.deepCopy();
        ((ObjectNode) duplicate.path("request")).put("requestId", "another-restore").put("expectedClaimRevision", 1);
        assertEquals(409, claimHttp(mira, offer, "mira", duplicate.toString()).statusCode());
    }

