    @Test
    void formatTwoInventoryGrantsCreateUsableStacksAndRejectCapsAtomically() throws Exception {
        installInventoryGrantActions();
        campaign.getActors().add(Campaign.Actor.builder().id("crafter").name("Ada").ownerId(playerId()).build());
        store.saveSheet(campaign.getId(), "crafter", """
                {"name":"Ada","hp":{"slots":6,"on":2},"stress":{"slots":6,"on":0},"inventory":[],
                 "features":[{"name":"Rally","automationSource":"classes:tester:features:rally","instanceId":"r"}]}
                """);
        String owner = cookie();
        String first = """
                {"request":{"requestId":"craft-first","expectedRevision":0,
                 "selections":[{"sourceInstanceId":"r","ruleId":"craft","bindingId":"sheet"}]}}
                """;
        var completed = automationHttp(owner, "crafter", first);
        assertEquals(200, completed.statusCode(), completed.body());
        JsonNode sheet = MAPPER.readTree(store.loadSheet(campaign.getId(), "crafter"));
        JsonNode item = sheet.at("/inventory/0");
        assertEquals("Minor Health Potion", item.path("name").asText());
        assertEquals(2, item.path("qty").asInt());
        assertEquals("consumables:minor-health-potion", item.path("automationSource").asText());
        assertFalse(item.path("instanceId").asText().isBlank());
        assertEquals("minor-health-potion", item.at("/catalog/id").asText());
        assertEquals("Clear 1d4 HP.", item.path("note").asText());
        assertEquals(1, sheet.path("inventoryRevision").asInt());
        assertTrue(MAPPER.readTree(automationHttp(owner, "crafter", null).body())
                .path("actions").findValuesAsText("ruleId").contains("drink"));
        assertEquals(completed.body(), automationHttp(owner, "crafter", first).body());
        String merge = first.replace("craft-first", "craft-merge").replace("\"expectedRevision\":0", "\"expectedRevision\":1")
                .replace("\"ruleId\":\"craft\"", "\"ruleId\":\"craft-one\"");
        var merged = automationHttp(owner, "crafter", merge);
        assertEquals(200, merged.statusCode(), merged.body());
        sheet = MAPPER.readTree(store.loadSheet(campaign.getId(), "crafter"));
        assertEquals(1, sheet.path("inventory").size());
        assertEquals(3, sheet.at("/inventory/0/qty").asInt());
        assertEquals(item.path("instanceId"), sheet.at("/inventory/0/instanceId"));
        assertEquals(2, sheet.path("inventoryRevision").asInt());
        assertEquals(merged.body(), automationHttp(owner, "crafter", merge).body());
        String saved = store.loadSheet(campaign.getId(), "crafter");
        int history = store.historyTail(campaign.getId(), 100).size();
        String second = first.replace("craft-first", "craft-second").replace("\"expectedRevision\":0", "\"expectedRevision\":2");
        var overCap = automationHttp(owner, "crafter", second);
        assertEquals(409, overCap.statusCode(), overCap.body());
        assertTrue(overCap.body().contains("limit of 3"), overCap.body());
        assertEquals(saved, store.loadSheet(campaign.getId(), "crafter"));
        assertEquals(history, store.historyTail(campaign.getId(), 100).size());
        String read = second.replace("craft-second", "craft-read").replace("\"ruleId\":\"craft\"", "\"ruleId\":\"craft-read\"");
        var staleRead = automationHttp(owner, "crafter", read);
        assertEquals(409, staleRead.statusCode(), staleRead.body());
        assertTrue(staleRead.body().contains("before its grant has been settled"), staleRead.body());
        ObjectNode multiple = (ObjectNode) MAPPER.readTree(second);
        ObjectNode intent = multiple.withObject("/request");
        intent.put("requestId", "craft-multiple");
        intent.withArray("selections").addObject().put("sourceInstanceId", "r").put("ruleId", "craft-one")
                .put("bindingId", "sheet");
        var unsequenced = automationHttp(owner, "crafter", multiple.toString());
        assertEquals(409, unsequenced.statusCode(), unsequenced.body());
        assertTrue(unsequenced.body().contains("multiple automation actions"), unsequenced.body());
        assertEquals(saved, store.loadSheet(campaign.getId(), "crafter"));
    }

    @Test
    void formatTwoInventoryGrantsHonorPartyCapsAndTargetRecipients() throws Exception {
        installInventoryGrantActions();
        String owner = cookie();
        allyCookie("offline-owner");
        campaign.getActors().add(Campaign.Actor.builder().id("crafter").name("Ada").ownerId(playerId()).build());
        campaign.getActors().add(Campaign.Actor.builder().id("ally").name("Mira").ownerId("offline-owner").build());
        campaign.getActors().add(Campaign.Actor.builder().id("disabled").name("Borin")
                .ownerId("offline-owner").disabled(true).build());
        store.saveSheet(campaign.getId(), "crafter", """
                {"name":"Ada","hp":{"slots":6,"on":2},"stress":{"slots":6,"on":0},"inventory":[],
                 "features":[{"name":"Rally","automationSource":"classes:tester:features:rally","instanceId":"r"}]}
                """);
        store.saveSheet(campaign.getId(), "ally", "{\"name\":\"Mira\",\"inventory\":[]}");
        store.saveSheet(campaign.getId(), "disabled", """
                {"name":"Borin","inventory":[{"name":"Foraged Relic","type":"consumable","qty":4,"foraged":true}]}
                """);
        String first = """
                {"request":{"requestId":"forage","expectedRevision":0,
                 "selections":[{"sourceInstanceId":"r","ruleId":"forage","bindingId":"sheet"}]}}
                """;
        String saved = store.loadSheet(campaign.getId(), "crafter");
        var rejected = automationHttp(owner, "crafter", first);
        assertEquals(409, rejected.statusCode(), rejected.body());
        assertTrue(rejected.body().contains("limit of 5"), rejected.body());
        assertEquals(saved, store.loadSheet(campaign.getId(), "crafter"));
        ObjectNode disabled = (ObjectNode) MAPPER.readTree(store.loadSheet(campaign.getId(), "disabled"));
        ((ObjectNode) disabled.at("/inventory/0")).put("qty", 3);
        store.saveSheet(campaign.getId(), "disabled", disabled.toString());
        var accepted = automationHttp(owner, "crafter", first);
        assertEquals(200, accepted.statusCode(), accepted.body());
        JsonNode foraged = MAPPER.readTree(store.loadSheet(campaign.getId(), "crafter")).at("/inventory/0");
        assertEquals(2, foraged.path("qty").asInt());
        assertTrue(foraged.path("foraged").asBoolean());
        var described = automationHttp(owner, "crafter", null);
        assertEquals(200, described.statusCode(), described.body());
        JsonNode actions = MAPPER.readTree(described.body()).path("actions");
        JsonNode gift = restDescriptor(actions, "gift");
        JsonNode options = gift.at("/targetSelection/options");
        assertEquals(List.of("ally"), options.findValuesAsText("id"));
        ObjectNode request = MAPPER.createObjectNode();
        ObjectNode intent = request.putObject("request").put("requestId", "gift").put("expectedRevision", 1);
        intent.putArray("selections").add(restSelection(gift));
        intent.putObject("target").put("recipientId", "ally").set("version", options.get(0).path("version"));
        var gifted = automationHttp(owner, "crafter", request.toString());
        assertEquals(200, gifted.statusCode(), gifted.body());
        JsonNode item = MAPPER.readTree(store.loadSheet(campaign.getId(), "ally")).at("/inventory/0");
        assertEquals("Spark Stone", item.path("name").asText());
        assertEquals("Glows faintly.", item.path("note").asText());
        assertEquals("spark-stone", item.at("/catalog/id").asText());
        assertEquals(gifted.body(), automationHttp(owner, "crafter", request.toString()).body());
    }

    private void installRestInventoryRules() throws Exception {
        installRestRules();
        Path file = compendiumDir.resolve("rules").resolve("ruleset.json");
        ObjectNode ruleset = (ObjectNode) MAPPER.readTree(file.toFile());
        ruleset.withObject("/automation").withArray("rules").addAll((ArrayNode) MAPPER.readTree("""
                [
                 {"id":"inventory-craft","bindings":[{"id":"move","event":"downtime.move","surface":"downtime",
                    "mode":"button","restMove":{"id":"craft","kind":"short"}}],
                  "costs":[{"op":"track.mark","track":"actor.stress","amount":1}],
                  "do":[{"op":"inventory.grant","catalog":"consumables","entry":"minor-health-potion",
                         "quantity":2,"tag":"foraged","max":5,"scope":"party","label":"Forage"}],
                  "ui":{"label":"Forage","report":"Found potions."}},
                 {"id":"inventory-craft-reaction","bindings":[{"id":"change","event":"track.changed",
                    "surface":"resource","mode":"automatic"}],
                  "when":{"eq":[{"read":"event.track"},"stress"]},
                  "do":[{"op":"resource.gain","pool":"actor.hope","amount":1}],
                  "ui":{"report":"Recovered Hope."}},
                 {"id":"inventory-count","bindings":[{"id":"move","event":"downtime.move","surface":"downtime",
                    "mode":"button","restMove":{"id":"count","kind":"short"}}],
                  "do":[{"op":"resource.gain","pool":"actor.hope",
                         "amount":{"size":{"read":"actor.inventory"}}}],
                  "ui":{"label":"Count","report":"Counted inventory."}},
                 {"id":"inventory-then-stress","bindings":[{"id":"move","event":"downtime.move","surface":"downtime",
                    "mode":"button","restMove":{"id":"unsafe","kind":"short"}}],
                  "do":[{"op":"inventory.grant","catalog":"consumables","entry":"minor-health-potion",
                         "quantity":1,"label":"Reward"},
                        {"op":"track.mark","track":"actor.stress","amount":1}],
                  "ui":{"label":"Unsafe order","report":"Updated inventory and Stress."}},
                 {"id":"inventory-gift","bindings":[{"id":"move","event":"downtime.move","surface":"downtime",
                    "mode":"button","restMove":{"id":"gift","kind":"short","ally":true},
                    "targetSelection":{"scope":"activePlayerCharacters","cardinality":"one","excludeSource":true}}],
                  "costs":[{"op":"track.mark","track":"actor.stress","amount":1}],
                  "do":[{"op":"track.clear","track":"recipient.stress","amount":1},
                        {"op":"inventory.grant","catalog":"consumables","entry":"minor-health-potion",
                         "quantity":1,"to":"recipient","label":"Gift"}],
                  "ui":{"label":"Give potion","report":"Gave a potion to {recipient.name}."}},
                 {"id":"inventory-gift-count","bindings":[{"id":"move","event":"downtime.move","surface":"downtime",
                    "mode":"button","restMove":{"id":"gift-count","kind":"short","ally":true},
                    "targetSelection":{"scope":"activePlayerCharacters","cardinality":"one","excludeSource":true}}],
                  "do":[{"op":"resource.gain","pool":"recipient.hope",
                         "amount":{"size":{"read":"recipient.inventory"}}}],
                  "ui":{"label":"Count ally supplies","report":"Counted ally supplies."}},
                 {"id":"inventory-gift-benefit","bindings":[{"id":"move","event":"downtime.move",
                    "surface":"downtime","mode":"option"}],
                  "when":{"eq":[{"read":"event.move.id"},"gift"]},
                  "after":{"do":[{"op":"resource.gain","pool":"actor.hope",
                                    "amount":{"size":{"read":"recipient.inventory"}}}],
                           "report":"The ally's supplies are ready."},
                  "ui":{"label":"Benefit from ally supplies"}},
                 {"id":"inventory-gift-failure","bindings":[{"id":"move","event":"downtime.move",
                    "surface":"downtime","mode":"option"}],
                  "when":{"eq":[{"read":"event.move.id"},"gift"]},
                  "after":{"costs":[{"op":"resource.spend","pool":"actor.hope","amount":6}]},
                  "ui":{"label":"Unaffordable benefit"}},
                 {"id":"before-inventory","bindings":[{"id":"rest","event":"rest.short","surface":"rest","mode":"option"}],
                  "do":[{"op":"inventory.grant","catalog":"consumables","entry":"minor-health-potion",
                         "quantity":1,"label":"Reward"}],
                  "ui":{"label":"Receive potion","report":"Received a potion."}},
                 {"id":"after-inventory","bindings":[{"id":"rest","event":"rest.short","surface":"rest",
                    "mode":"option","restPhase":"afterReset"}],
                  "when":{"gt":[{"size":{"read":"actor.inventory"}},0]},
                  "do":[{"op":"resource.gain","pool":"actor.hope","amount":1}],
                  "ui":{"label":"Use supplies","report":"Supplies are ready."}}
                ]
                """));
        java.nio.file.Files.writeString(file, ruleset.toString());
    }

    @Test
    void directRestSettlesInventoryBeforeLaterMovesAndRejectsPartyCaps() throws Exception {
        installRestInventoryRules();
        String owner = cookie();
        campaign.getActors().add(Campaign.Actor.builder().id("resting").name("Ada").ownerId(playerId()).build());
        campaign.getActors().add(Campaign.Actor.builder().id("retired").name("Borin")
                .ownerId(playerId()).disabled(true).build());
        store.saveSheet(campaign.getId(), "resting", """
                {"name":"Ada","hp":{"slots":6,"on":2},"stress":{"slots":6,"on":0},
                 "armorTrack":{"slots":3,"on":0},"hope":{"slots":6,"on":0},"inventory":[]}
                """);
        store.saveSheet(campaign.getId(), "retired", """
                {"name":"Borin","inventory":[{"name":"Foraged Relic","type":"consumable","qty":4,"foraged":true}]}
                """);
        JsonNode offer = MAPPER.readTree(restHttp(owner, "resting", "short", null).body());
        ObjectNode unsafe = restRequest(offer, "unsafe-grant");
        addRestMove((ObjectNode) unsafe.path("request"), restDescriptor(offer.path("moves"), "inventory-then-stress"));
        String original = store.loadSheet(campaign.getId(), "resting");
        var unsafeResult = restHttp(owner, "resting", null, unsafe.toString());
        assertEquals(409, unsafeResult.statusCode(), unsafeResult.body());
        assertTrue(unsafeResult.body().contains("later track reaction"), unsafeResult.body());
        assertEquals(original, store.loadSheet(campaign.getId(), "resting"));
        ObjectNode body = restRequest(offer, "rest-forage");
        addRestMove((ObjectNode) body.path("request"), restDescriptor(offer.path("moves"), "inventory-craft"));
        addRestMove((ObjectNode) body.path("request"), restDescriptor(offer.path("moves"), "inventory-count"));
        var overCap = restHttp(owner, "resting", null, body.toString());
        assertEquals(409, overCap.statusCode(), overCap.body());
        assertTrue(overCap.body().contains("limit of 5"), overCap.body());
        assertEquals(original, store.loadSheet(campaign.getId(), "resting"));
        ObjectNode retired = (ObjectNode) MAPPER.readTree(store.loadSheet(campaign.getId(), "retired"));
        ((ObjectNode) retired.at("/inventory/0")).put("qty", 3);
        store.saveSheet(campaign.getId(), "retired", retired.toString());
        var completed = restHttp(owner, "resting", null, body.toString());
        assertEquals(200, completed.statusCode(), completed.body());
        JsonNode sheet = MAPPER.readTree(store.loadSheet(campaign.getId(), "resting"));
        assertEquals(2, sheet.at("/inventory/0/qty").asInt());
        assertTrue(sheet.at("/inventory/0/foraged").asBoolean());
        assertEquals(2, sheet.at("/hope/on").asInt());
        assertEquals(completed.body(), restHttp(owner, "resting", null, body.toString()).body());
        assertEquals(sheet, MAPPER.readTree(store.loadSheet(campaign.getId(), "resting")));
    }

    @Test
    void interactiveRestSettlesBeforeResetGrantsBeforeOfferingAfterResetChoices() throws Exception {
        installRestInventoryRules();
        String owner = cookie();
        campaign.getActors().add(Campaign.Actor.builder().id("resting").name("Ada").ownerId(playerId()).build());
        store.saveSheet(campaign.getId(), "resting", """
                {"name":"Ada","hp":{"slots":6,"on":2},"stress":{"slots":6,"on":0},
                 "armorTrack":{"slots":3,"on":0},"hope":{"slots":6,"on":0},"inventory":[]}
                """);
        String original = store.loadSheet(campaign.getId(), "resting");
        JsonNode offer = MAPPER.readTree(restHttp(owner, "resting", "short", null).body());
        ObjectNode body = restRequest(offer, "rest-inventory-choice");
        var first = restChoiceHttp(owner, "resting", "choices", body);
        assertEquals(200, first.statusCode(), first.body());
        JsonNode before = MAPPER.readTree(first.body());
        ObjectNode advance = MAPPER.createObjectNode().put("requestId", "rest-inventory-choice")
                .put("choiceVersion", before.path("choiceVersion").asText());
        advance.putArray("selections").add(restSelection(restDescriptor(before.path("actions"), "before-inventory")));
        var second = restChoiceHttp(owner, "resting", "choices", advance);
        assertEquals(200, second.statusCode(), second.body());
        JsonNode after = MAPPER.readTree(second.body());
        assertTrue(restDescriptor(after.path("actions"), "after-inventory").path("available").asBoolean());
        assertEquals(original, store.loadSheet(campaign.getId(), "resting"));
        ObjectNode request = ((ObjectNode) body.path("request")).deepCopy();
        request.withArray("completion").add(advance.at("/selections/0").deepCopy())
                .add(restSelection(restDescriptor(after.path("actions"), "after-inventory")));
        ObjectNode complete = MAPPER.createObjectNode().put("choiceVersion", after.path("choiceVersion").asText());
        complete.set("request", request);
        var committed = restChoiceHttp(owner, "resting", "complete", complete);
        assertEquals(200, committed.statusCode(), committed.body());
        JsonNode sheet = MAPPER.readTree(store.loadSheet(campaign.getId(), "resting"));
        assertEquals(1, sheet.at("/inventory/0/qty").asInt());
        assertEquals(1, sheet.at("/hope/on").asInt());
        assertEquals(committed.body(), restChoiceHttp(owner, "resting", "complete", complete).body());
        assertEquals(sheet, MAPPER.readTree(store.loadSheet(campaign.getId(), "resting")));
    }

    @Test
    void interactiveRestInventoryRejectsChangedPartySheetsAndMembership() throws Exception {
        installRestInventoryRules();
        String owner = cookie();
        campaign.getActors().add(Campaign.Actor.builder().id("resting").name("Ada").ownerId(playerId()).build());
        campaign.getActors().add(Campaign.Actor.builder().id("retired").name("Borin")
                .ownerId(playerId()).disabled(true).build());
        store.saveSheet(campaign.getId(), "resting", """
                {"name":"Ada","hp":{"slots":6,"on":2},"stress":{"slots":6,"on":0},
                 "armorTrack":{"slots":3,"on":0},"hope":{"slots":6,"on":0},"inventory":[]}
                """);
        store.saveSheet(campaign.getId(), "retired", "{\"name\":\"Borin\",\"inventory\":[]}");
        String original = store.loadSheet(campaign.getId(), "resting");
        int history = store.historyTail(campaign.getId(), 100).size();
        for (String id : List.of("changed-sheet", "changed-membership")) {
            JsonNode offer = MAPPER.readTree(restHttp(owner, "resting", "short", null).body());
            ObjectNode body = restRequest(offer, id);
            addRestMove((ObjectNode) body.path("request"), restDescriptor(offer.path("moves"), "inventory-craft"));
            var first = restChoiceHttp(owner, "resting", "choices", body);
            assertEquals(200, first.statusCode(), first.body());
            ObjectNode advance = MAPPER.createObjectNode().put("requestId", id)
                    .put("choiceVersion", MAPPER.readTree(first.body()).path("choiceVersion").asText());
            advance.putArray("selections");
            var second = restChoiceHttp(owner, "resting", "choices", advance);
            assertEquals(200, second.statusCode(), second.body());
            if ("changed-sheet".equals(id))
                store.saveSheet(campaign.getId(), "retired",
                        "{\"name\":\"Borin\",\"inventory\":[{\"name\":\"Foraged Relic\",\"qty\":1,\"foraged\":true}]}");
            else
                campaign.getActors().add(Campaign.Actor.builder().id("late").name("Late")
                        .ownerId(playerId()).disabled(true).build());
            ObjectNode complete = MAPPER.createObjectNode()
                    .put("choiceVersion", MAPPER.readTree(second.body()).path("choiceVersion").asText());
            complete.set("request", body.path("request").deepCopy());
            var rejected = restChoiceHttp(owner, "resting", "complete", complete);
            assertEquals(409, rejected.statusCode(), rejected.body());
            assertEquals(original, store.loadSheet(campaign.getId(), "resting"));
            assertEquals(history, store.historyTail(campaign.getId(), 100).size());
        }
    }

    @Test
    void targetedRestGrantsAreVisibleToLaterAllyMovesAndKeepTrackReactions() throws Exception {
        installRestInventoryRules();
        String owner = cookie();
        campaign.getActors().add(Campaign.Actor.builder().id("resting").name("Ada").ownerId(playerId()).build());
        campaign.getActors().add(Campaign.Actor.builder().id("ally").name("Mira").ownerId(playerId()).build());
        for (String id : List.of("resting", "ally"))
            store.saveSheet(campaign.getId(), id, """
                    {"name":"%s","hp":{"slots":6,"on":2},"stress":{"slots":6,"on":1},
                     "armorTrack":{"slots":3,"on":0},"hope":{"slots":6,"on":0},"inventory":[]}
                    """.formatted(id));
        JsonNode offer = MAPPER.readTree(restHttp(owner, "resting", "short", null).body());
        ObjectNode body = restRequest(offer, "target-gift");
        for (String rule : List.of("inventory-gift", "inventory-gift-count")) {
            JsonNode descriptor = restDescriptor(offer.path("moves"), rule);
            JsonNode option = descriptor.at("/targetSelection/options/0");
            assertEquals("ally", option.path("id").asText());
            addRestMove((ObjectNode) body.path("request"), descriptor).putObject("target")
                    .put("recipientId", "ally").put("version", option.path("version").asText());
        }
        var completed = restHttp(owner, "resting", null, body.toString());
        assertEquals(200, completed.statusCode(), completed.body());
        JsonNode source = MAPPER.readTree(store.loadSheet(campaign.getId(), "resting"));
        JsonNode ally = MAPPER.readTree(store.loadSheet(campaign.getId(), "ally"));
        assertEquals(1, source.at("/hope/on").asInt());
        assertEquals(0, ally.at("/stress/on").asInt());
        assertEquals(2, ally.at("/hope/on").asInt());
        assertEquals(1, ally.at("/inventory/0/qty").asInt());
        assertEquals("consumables:minor-health-potion", ally.at("/inventory/0/automationSource").asText());
        assertEquals(completed.body(), restHttp(owner, "resting", null, body.toString()).body());
    }

    @Test
    void targetedRestSettlesInventoryBeforeDeferredBenefitsAndRollsBackOnFailure() throws Exception {
        installRestInventoryRules();
        String owner = cookie();
        campaign.getActors().add(Campaign.Actor.builder().id("resting").name("Ada").ownerId(playerId()).build());
        campaign.getActors().add(Campaign.Actor.builder().id("ally").name("Mira").ownerId(playerId()).build());
        for (String id : List.of("resting", "ally"))
            store.saveSheet(campaign.getId(), id, """
                    {"name":"%s","hp":{"slots":6,"on":2},"stress":{"slots":6,"on":1},
                     "armorTrack":{"slots":3,"on":0},"hope":{"slots":6,"on":0},"inventory":[]}
                    """.formatted(id));
        String originalSource = store.loadSheet(campaign.getId(), "resting");
        String originalAlly = store.loadSheet(campaign.getId(), "ally");
        int history = store.historyTail(campaign.getId(), 100).size();
        JsonNode offer = MAPPER.readTree(restHttp(owner, "resting", "short", null).body());
        JsonNode gift = restDescriptor(offer.path("moves"), "inventory-gift");
        JsonNode target = gift.at("/targetSelection/options/0");

        ObjectNode failure = restRequest(offer, "failed-gift-benefit");
        ObjectNode failedMove = addRestMove((ObjectNode) failure.path("request"), gift);
        failedMove.putObject("target").put("recipientId", "ally").put("version", target.path("version").asText());
        failedMove.withArray("options").add(restSelection(restDescriptor(gift.path("options"), "inventory-gift-failure")));
        var rejected = restChoiceHttp(owner, "resting", "choices", failure);
        assertEquals(409, rejected.statusCode(), rejected.body());
        assertEquals(originalSource, store.loadSheet(campaign.getId(), "resting"));
        assertEquals(originalAlly, store.loadSheet(campaign.getId(), "ally"));
        assertEquals(history, store.historyTail(campaign.getId(), 100).size());

        ObjectNode body = restRequest(offer, "gift-benefit");
        ObjectNode move = addRestMove((ObjectNode) body.path("request"), gift);
        move.putObject("target").put("recipientId", "ally").put("version", target.path("version").asText());
        move.withArray("options").add(restSelection(restDescriptor(gift.path("options"), "inventory-gift-benefit")));
        var first = restChoiceHttp(owner, "resting", "choices", body);
        assertEquals(200, first.statusCode(), first.body());
        assertTrue(MAPPER.readTree(first.body()).path("reports").toString().contains("The ally's supplies are ready."));
        assertEquals(originalSource, store.loadSheet(campaign.getId(), "resting"));
        assertEquals(originalAlly, store.loadSheet(campaign.getId(), "ally"));
        ObjectNode advance = MAPPER.createObjectNode().put("requestId", "gift-benefit")
                .put("choiceVersion", MAPPER.readTree(first.body()).path("choiceVersion").asText());
        advance.putArray("selections");
        var after = restChoiceHttp(owner, "resting", "choices", advance);
        assertEquals(200, after.statusCode(), after.body());
        ObjectNode complete = MAPPER.createObjectNode()
                .put("choiceVersion", MAPPER.readTree(after.body()).path("choiceVersion").asText());
        complete.set("request", body.path("request").deepCopy());
        var committed = restChoiceHttp(owner, "resting", "complete", complete);
        assertEquals(200, committed.statusCode(), committed.body());
        JsonNode source = MAPPER.readTree(store.loadSheet(campaign.getId(), "resting"));
        JsonNode ally = MAPPER.readTree(store.loadSheet(campaign.getId(), "ally"));
        assertEquals(2, source.at("/hope/on").asInt());
        assertEquals(1, ally.at("/hope/on").asInt());
        assertEquals(0, ally.at("/stress/on").asInt());
        assertEquals(1, ally.at("/inventory/0/qty").asInt());
        assertEquals(committed.body(), restChoiceHttp(owner, "resting", "complete", complete).body());
    }

    @Test
    void postOutcomeRestChoicesStageEachPhaseAndCommitTheSampledMovesOnce() throws Exception {
        installRestRules();
        Path file = compendiumDir.resolve("rules").resolve("ruleset.json");
        ObjectNode ruleset = (ObjectNode) MAPPER.readTree(file.toFile());
        ruleset.withObject("/automation").withArray("rules").addAll((ArrayNode) MAPPER.readTree("""
                [
                 {"id":"outcome-benefit","bindings":[{"id":"rest","event":"rest.short","surface":"rest","mode":"option"}],
                  "when":{"gt":[{"read":"event.rest.cleared.stress"},0]},
                  "do":[{"op":"resource.gain","pool":"actor.hope","amount":1}],
                  "ui":{"label":"Reward recovery","report":"Recovery rewarded."}},
                 {"id":"reset-benefit","bindings":[{"id":"rest","event":"rest.short","surface":"rest","mode":"option",
                   "restPhase":"afterReset"}],
                  "when":{"gte":[{"read":"actor.hope.value"},2]},
                  "do":[{"op":"resource.gain","pool":"actor.hope","amount":1}],
                  "ui":{"label":"Reward Hope","report":"Hope rewarded."}}
                ]
                """));
        java.nio.file.Files.writeString(file, ruleset.toString());
        campaign.getActors().add(Campaign.Actor.builder().id("resting").name("Ada").ownerId(playerId()).build());
        store.saveSheet(campaign.getId(), "resting", """
                {"name":"Ada","level":1,"hp":{"slots":6,"on":2},"stress":{"slots":6,"on":3},
                 "armorTrack":{"slots":3,"on":0},"hope":{"slots":6,"on":1}}
                """);
        String owner = cookie(), other = allyCookie("outcome-viewer");
        String initialSheet = store.loadSheet(campaign.getId(), "resting");
        int history = store.historyTail(campaign.getId(), 100).size();
        JsonNode rest = MAPPER.readTree(restHttp(owner, "resting", "short", null).body());
        assertTrue(rest.path("postOutcomeChoices").asBoolean());
        assertFalse(restDescriptor(rest.path("completion"), "outcome-benefit").path("available").asBoolean());
        ObjectNode body = restRequest(rest, "outcome-rest");
        addRestMove((ObjectNode) body.path("request"), restDescriptor(rest.path("moves"), "rest-stress"));
        assertEquals(403, restChoiceHttp(other, "resting", "choices", body).statusCode());
        var first = restChoiceHttp(owner, "resting", "choices", body);
        assertEquals(200, first.statusCode(), first.body());
        JsonNode before = MAPPER.readTree(first.body());
        assertEquals("beforeReset", before.path("phase").asText());
        assertTrue(before.at("/cleared/stress").asInt() > 0);
        assertTrue(restDescriptor(before.path("actions"), "outcome-benefit").path("available").asBoolean());
        assertEquals(first.body(), restChoiceHttp(owner, "resting", "choices", body).body());
        assertEquals(initialSheet, store.loadSheet(campaign.getId(), "resting"));
        assertEquals(history, store.historyTail(campaign.getId(), 100).size());

        ObjectNode advance = MAPPER.createObjectNode().put("requestId", "outcome-rest")
                .put("choiceVersion", before.path("choiceVersion").asText());
        advance.putArray("selections").add(restSelection(restDescriptor(before.path("actions"), "outcome-benefit")));
        ObjectNode forged = advance.deepCopy().put("choiceVersion", "rest-choice-v1.forged");
        assertEquals(409, restChoiceHttp(owner, "resting", "choices", forged).statusCode());
        ObjectNode unoffered = advance.deepCopy();
        ((ObjectNode) unoffered.at("/selections/0")).put("ruleId", "reset-benefit");
        assertEquals(400, restChoiceHttp(owner, "resting", "choices", unoffered).statusCode());
        var second = restChoiceHttp(owner, "resting", "choices", advance);
        assertEquals(200, second.statusCode(), second.body());
        JsonNode after = MAPPER.readTree(second.body());
        assertEquals("afterReset", after.path("phase").asText());
        assertTrue(restDescriptor(after.path("actions"), "reset-benefit").path("available").asBoolean());
        assertEquals(second.body(), restChoiceHttp(owner, "resting", "choices", advance).body());
        assertEquals(initialSheet, store.loadSheet(campaign.getId(), "resting"));

        ObjectNode request = ((ObjectNode) body.path("request")).deepCopy();
        request.withArray("completion").add(advance.at("/selections/0").deepCopy())
                .add(restSelection(restDescriptor(after.path("actions"), "reset-benefit")));
        ObjectNode complete = MAPPER.createObjectNode().put("choiceVersion", after.path("choiceVersion").asText());
        complete.set("request", request);
        ObjectNode wrongToken = complete.deepCopy().put("choiceVersion", before.path("choiceVersion").asText());
        assertEquals(409, restChoiceHttp(owner, "resting", "complete", wrongToken).statusCode());
        var committed = restChoiceHttp(owner, "resting", "complete", complete);
        assertEquals(200, committed.statusCode(), committed.body());
        JsonNode saved = MAPPER.readTree(store.loadSheet(campaign.getId(), "resting"));
        assertEquals(3, saved.at("/hope/on").asInt());
        assertEquals(3 - before.at("/cleared/stress").asInt(), saved.at("/stress/on").asInt());
        int published = store.historyTail(campaign.getId(), 100).size();
        assertTrue(published > history);
        assertEquals(committed.body(), restChoiceHttp(owner, "resting", "complete", complete).body());
        assertEquals(saved, MAPPER.readTree(store.loadSheet(campaign.getId(), "resting")));
        assertEquals(published, store.historyTail(campaign.getId(), 100).size());
        server.stop();
        server.start();
        assertEquals(committed.body(), restChoiceHttp(cookie(), "resting", "complete", complete).body());
        assertEquals(saved, MAPPER.readTree(store.loadSheet(campaign.getId(), "resting")));
        assertEquals(published, store.historyTail(campaign.getId(), 100).size());
    }

    private void installPartyRestRules(String fearOperation) throws Exception {
        installRestRules();
        Path file = compendiumDir.resolve("rules").resolve("ruleset.json");
        ObjectNode ruleset = (ObjectNode) MAPPER.readTree(file.toFile());
        ArrayNode definitions = ruleset.withObject("/automation").withArray("rules");
        definitions.add(MAPPER.readTree("""
                {"id":"share-repair","bindings":[{"id":"move","event":"downtime.move","surface":"downtime","mode":"automatic"}],
                 "when":{"and":[{"eq":[{"read":"event.move.id"},"tend"]},
                                  {"eq":[{"read":"event.move.ally"},false]}]},
                 "do":[{"op":"plan.adjust","plan":"event.move","field":"allies","by":2,"label":"Shared repair",
                        "partyRecovery":{"track":"armorTrack","scope":"activePlayerCharacters"}}],"ui":{}}
                """));
        definitions.add(MAPPER.readTree("""
                {"id":"overflow","bindings":[{"id":"changed","event":"track.changed","surface":"resource","mode":"automatic"}],
                 "when":{"and":[{"eq":[{"read":"event.track"},"armorTrack"]},
                                  {"eq":[{"read":"event.change"},"clear"]},
                                  {"gt":[{"read":"event.requested"},
                                         {"subtract":[{"read":"event.before.marked"},{"read":"event.after.marked"}]}]}]},
                 "do":[{"op":"resource.gain","pool":"actor.hope","amount":1},
                       {"op":"table.%s","resource":"fear","amount":1,"label":"Overflow"}],
                 "ui":{"report":"Overflow for {actor.name}."}}
                """.formatted(fearOperation)));
        java.nio.file.Files.writeString(file, ruleset.toString());
    }

    private void addRestParty() throws Exception {
        for (String id : List.of("resting", "mira", "borin", "retired"))
            campaign.getActors().add(Campaign.Actor.builder().id(id).name(id).ownerId(playerId())
                    .disabled("retired".equals(id)).build());
        for (String id : List.of("resting", "mira", "borin", "retired")) {
            int armor = "mira".equals(id) ? 1 : "resting".equals(id) || "retired".equals(id) ? 2 : 0;
            store.saveSheet(campaign.getId(), id, """
                    {"name":"%s","level":1,"hp":{"slots":6,"on":4},"stress":{"slots":6,"on":2},
                     "armorTrack":{"slots":3,"on":%d},"hope":{"slots":6,"on":0}}
                    """.formatted(id, armor));
        }
    }

    @Test
    void formatTwoRestCommitsPartyRecoveryAndRecipientReactionsOnce() throws Exception {
        installPartyRestRules("gain");
        addRestParty();
        String owner = cookie(), retired = store.loadSheet(campaign.getId(), "retired");
        int fear = campaign.getFear();
        var described = restHttp(owner, "resting", "short", null);
        assertEquals(200, described.statusCode(), described.body());
        JsonNode offer = MAPPER.readTree(described.body());
        ObjectNode body = restRequest(offer, "shared-rest");
        addRestMove((ObjectNode) body.path("request"), restDescriptor(offer.path("moves"), "rest-tend"));
        var completed = restHttp(owner, "resting", null, body.toString());
        assertEquals(200, completed.statusCode(), completed.body());
        JsonNode receipt = MAPPER.readTree(completed.body());
        assertEquals(List.of("mira", "borin"), receipt.path("partyRecoveries").findValuesAsText("holderId"));
        assertEquals(List.of(1, 0), receipt.path("partyRecoveries").findValues("cleared").stream().map(JsonNode::asInt).toList());
        assertEquals(fear + 2, campaign.getFear());
        assertEquals(fear + 2, store.load(campaign.getId()).getFear());
        for (String id : List.of("mira", "borin")) {
            JsonNode saved = MAPPER.readTree(store.loadSheet(campaign.getId(), id));
            assertEquals(0, saved.at("/armorTrack/on").asInt());
            assertEquals(1, saved.at("/hope/on").asInt());
            assertEquals(1, saved.at("/automationState/revision").asInt());
        }
        assertEquals(retired, store.loadSheet(campaign.getId(), "retired"));
        List<JsonNode> messages = store.historyTail(campaign.getId(), 100);
        assertTrue(messages.stream().anyMatch(message -> message.path("text").asText().contains("mira cleared 1 armorTrack")));
        assertTrue(messages.stream().anyMatch(message -> message.path("text").asText().contains("Overflow for borin.")));
        int history = messages.size();
        String mira = store.loadSheet(campaign.getId(), "mira"), borin = store.loadSheet(campaign.getId(), "borin");
        campaign.actor("mira").setDisabled(true);
        assertEquals(completed.body(), restHttp(owner, "resting", null, body.toString()).body());
        assertEquals(mira, store.loadSheet(campaign.getId(), "mira"));
        assertEquals(borin, store.loadSheet(campaign.getId(), "borin"));
        assertEquals(history, store.historyTail(campaign.getId(), 100).size());
        assertEquals(fear + 2, campaign.getFear());
    }

    @Test
    void convertedArmorOverflowTriggersForSelfAndAllyRestRecovery() throws Exception {
        installRestRules();
        var converted = dmmt.online.automation.LegacyCatalogConverter.convert("""
                {"format":"dmmap-daggerheart","version":1,"category":"armor","entries":[
                 {"id":"plate","name":"Overflow Plate","automation":{"overflowHope":1}}]}
                """);
        assertEquals(1, converted.converted(), converted.diagnostics().toString());
        java.nio.file.Files.writeString(compendiumDir.resolve("armor.json"), converted.catalog().toString());
        addRestParty();
        for (String id : List.of("resting", "mira")) {
            ObjectNode sheet = (ObjectNode) MAPPER.readTree(store.loadSheet(campaign.getId(), id));
            sheet.putObject("activeArmor").put("name", "Overflow Plate").put("instanceId", "plate")
                    .put("automationSource", "armor:plate");
            store.saveSheet(campaign.getId(), id, sheet.toString());
        }
        String owner = cookie();
        for (boolean ally : List.of(false, true)) {
            JsonNode rest = MAPPER.readTree(restHttp(owner, "resting", "short", null).body());
            ObjectNode body = restRequest(rest, "armor-overflow-" + ally);
            if (ally) targetRestMove(body, rest, "rest-repair-ally", "mira");
            else addRestMove((ObjectNode) body.path("request"), restDescriptor(rest.path("moves"), "rest-repair"));
            diceSeed(seedForDie(4, 4));
            var completed = restHttp(owner, "resting", null, body.toString());
            assertEquals(200, completed.statusCode(), completed.body());
            JsonNode result = MAPPER.readTree(completed.body());
            assertEquals(1, result.path("actions").findValuesAsText("ruleId").stream()
                    .filter("overflow-hope"::equals).count());
            int history = store.historyTail(campaign.getId(), 100).size();
            assertEquals(completed.body(), restHttp(owner, "resting", null, body.toString()).body());
            assertEquals(history, store.historyTail(campaign.getId(), 100).size());
        }
        for (String id : List.of("resting", "mira")) {
            JsonNode saved = MAPPER.readTree(store.loadSheet(campaign.getId(), id));
            assertEquals(0, saved.at("/armorTrack/on").asInt());
            assertEquals(1, saved.at("/hope/on").asInt());
        }
    }

