    private void addAutomaticRestPreparationRoll() throws Exception {
        Path file = compendiumDir.resolve("rules").resolve("ruleset.json");
        ObjectNode ruleset = (ObjectNode) MAPPER.readTree(file.toFile());
        ruleset.withObject("/automation").withArray("rules").add(MAPPER.readTree("""
                {"id":"random-before-choice","bindings":[{"id":"rest","event":"rest.prepare","surface":"rest","mode":"automatic"}],
                 "do":[{"op":"dice.roll","count":1,"sides":4,"as":"roll"},
                       {"op":"plan.adjust","plan":"event.rest","field":"moves","by":{"read":"result.roll"},"label":"Extra time"}],
                 "ui":{"label":"Roll before rest","report":"Preparation rolled {result.roll}."}}
                """));
        java.nio.file.Files.writeString(file, ruleset.toString());
    }

    @Test
    void formatTwoRestRetainsAutomaticPreparationRollsWhileChoosingMoves() throws Exception {
        installRestRules();
        addAutomaticRestPreparationRoll();
        campaign.getActors().add(Campaign.Actor.builder().id("resting").name("Ada").ownerId(playerId()).build());
        store.saveSheet(campaign.getId(), "resting", """
                {"name":"Ada","hp":{"slots":6,"on":1},"stress":{"slots":6,"on":1},
                 "armorTrack":{"slots":4,"on":1},"hope":{"slots":6,"on":1}}
                """);
        String owner = cookie(), other = allyCookie("other-rest-player");
        String original = store.loadSheet(campaign.getId(), "resting");
        int history = store.historyTail(campaign.getId(), 100).size();
        var described = restHttp(owner, "resting", "short", null);
        assertEquals(200, described.statusCode(), described.body());
        JsonNode offer = MAPPER.readTree(described.body());
        assertTrue(offer.path("prepareBeforeMoves").asBoolean());
        assertTrue(offer.path("moves").isEmpty());
        ObjectNode body = restRequest(offer, "random-preparation");
        body.withObject("/request").withArray("preparation")
                .add(restSelection(restDescriptor(offer.path("preparation"), "test-extra")));
        assertEquals(409, restHttp(owner, "resting", null, body.toString()).statusCode());
        assertEquals(409, restChoiceHttp(owner, "resting", "choices", body).statusCode());
        ObjectNode preparing = body.deepCopy().put("prepare", true);
        assertEquals(403, restChoiceHttp(other, "resting", "choices", preparing).statusCode());
        diceSeed(0);
        var first = restChoiceHttp(owner, "resting", "choices", preparing);
        assertEquals(200, first.statusCode(), first.body());
        JsonNode prepared = MAPPER.readTree(first.body());
        int allowance = prepared.at("/plan/moves").asInt();
        assertTrue(allowance >= 4 && allowance <= 7, prepared.toString());
        String report = java.util.stream.StreamSupport.stream(prepared.path("reports").spliterator(), false)
                .map(JsonNode::asText).filter(text -> text.startsWith("Preparation rolled ")).findFirst().orElseThrow();
        assertFalse(prepared.path("moves").isEmpty());
        assertEquals(first.body(), restChoiceHttp(owner, "resting", "choices", preparing).body());
        ObjectNode changedPreparation = preparing.deepCopy();
        ((ArrayNode) changedPreparation.at("/request/preparation")).removeAll();
        assertEquals(409, restChoiceHttp(owner, "resting", "choices", changedPreparation).statusCode());
        assertEquals(original, store.loadSheet(campaign.getId(), "resting"));
        assertEquals(history, store.historyTail(campaign.getId(), 100).size());

        ObjectNode selected = body.deepCopy();
        addRestMove((ObjectNode) selected.path("request"), restDescriptor(prepared.path("moves"), "rest-stress"));
        selected.put("preparedVersion", "forged");
        assertEquals(409, restChoiceHttp(owner, "resting", "choices", selected).statusCode());
        selected.put("preparedVersion", prepared.path("choiceVersion").asText());
        var moves = restChoiceHttp(owner, "resting", "choices", selected);
        assertEquals(200, moves.statusCode(), moves.body());
        JsonNode beforeReset = MAPPER.readTree(moves.body());
        assertTrue(beforeReset.path("reports").toString().contains(report));
        assertEquals(moves.body(), restChoiceHttp(owner, "resting", "choices", selected).body());
        ObjectNode beforeChoice = MAPPER.createObjectNode().put("requestId", "random-preparation")
                .put("choiceVersion", beforeReset.path("choiceVersion").asText());
        beforeChoice.putArray("selections");
        var after = restChoiceHttp(owner, "resting", "choices", beforeChoice);
        assertEquals(200, after.statusCode(), after.body());
        ObjectNode complete = MAPPER.createObjectNode()
                .put("choiceVersion", MAPPER.readTree(after.body()).path("choiceVersion").asText());
        complete.set("request", selected.path("request").deepCopy());
        var completed = restChoiceHttp(owner, "resting", "complete", complete);
        assertEquals(200, completed.statusCode(), completed.body());
        JsonNode receipt = MAPPER.readTree(completed.body());
        assertEquals(allowance, receipt.at("/preparationEvent/rest/moves").asInt());
        assertTrue(receipt.path("actions").findValuesAsText("report").contains(report));
        assertEquals(completed.body(), restChoiceHttp(owner, "resting", "complete", complete).body());
    }

    @Test
    void preparedRestRejectsStaleRecipientWithoutPublishingOrSpending() throws Exception {
        installTargetRestRules("gain");
        addAutomaticRestPreparationRoll();
        addRestParty();
        String owner = cookie();
        String source = store.loadSheet(campaign.getId(), "resting");
        String recipient = store.loadSheet(campaign.getId(), "mira");
        String other = store.loadSheet(campaign.getId(), "borin");
        int fear = campaign.getFear(), history = store.historyTail(campaign.getId(), 100).size();
        JsonNode offer = MAPPER.readTree(restHttp(owner, "resting", "short", null).body());
        ObjectNode body = restRequest(offer, "prepared-target");
        ObjectNode preparing = body.deepCopy().put("prepare", true);
        var response = restChoiceHttp(owner, "resting", "choices", preparing);
        assertEquals(200, response.statusCode(), response.body());
        JsonNode prepared = MAPPER.readTree(response.body());
        targetRestMove(body, prepared, "mira");
        body.put("preparedVersion", prepared.path("choiceVersion").asText());

        ObjectNode changed = (ObjectNode) MAPPER.readTree(recipient);
        changed.put("notes", "Changed elsewhere");
        store.saveSheet(campaign.getId(), "mira", changed.toString());
        assertEquals(409, restChoiceHttp(owner, "resting", "choices", body).statusCode());
        assertEquals(source, store.loadSheet(campaign.getId(), "resting"));
        assertEquals(other, store.loadSheet(campaign.getId(), "borin"));
        assertEquals(fear, campaign.getFear());
        assertEquals(history, store.historyTail(campaign.getId(), 100).size());

        store.saveSheet(campaign.getId(), "mira", recipient);
        var moves = restChoiceHttp(owner, "resting", "choices", body);
        assertEquals(200, moves.statusCode(), moves.body());
        ObjectNode advance = MAPPER.createObjectNode().put("requestId", "prepared-target")
                .put("choiceVersion", MAPPER.readTree(moves.body()).path("choiceVersion").asText());
        advance.putArray("selections");
        var after = restChoiceHttp(owner, "resting", "choices", advance);
        assertEquals(200, after.statusCode(), after.body());
        store.saveSheet(campaign.getId(), "mira", changed.toString());
        ObjectNode complete = MAPPER.createObjectNode()
                .put("choiceVersion", MAPPER.readTree(after.body()).path("choiceVersion").asText());
        complete.set("request", body.path("request").deepCopy());
        var rejected = restChoiceHttp(owner, "resting", "complete", complete);
        assertEquals(409, rejected.statusCode(), rejected.body());
        assertEquals(source, store.loadSheet(campaign.getId(), "resting"));
        assertEquals(changed, MAPPER.readTree(store.loadSheet(campaign.getId(), "mira")));
        assertEquals(other, store.loadSheet(campaign.getId(), "borin"));
        assertEquals(fear, campaign.getFear());
        assertEquals(history, store.historyTail(campaign.getId(), 100).size());
    }

    private HttpResponse<String> resultHttp(String cookie, String actorId, String resultId) throws Exception {
        return http.send(HttpRequest.newBuilder(URI.create("http://localhost:" + port + "/api/automation/"
                + OnlineProtocol.AUTOMATION_COMPATIBILITY_VERSION + "/" + actorId
                + "?resultId=" + resultId)).header("Cookie", cookie).GET().build(), HttpResponse.BodyHandlers.ofString());
    }

    @Test
    void automationVersionIsEnforcedBeforeReadingOrMutatingAnySheet() throws Exception {
        automationCompendium();
        campaign.getActors().add(Campaign.Actor.builder().id("auto").name("Auto").ownerId(playerId()).build());
        String original = """
            {"name":"Auto","hope":{"slots":6,"on":1},"features":[
             {"name":"Rally","automationSource":"classes:tester:features:rally","instanceId":"r"}]}""";
        store.saveSheet(campaign.getId(), "auto", original);
        String saved = store.loadSheet(campaign.getId(), "auto");
        String cookie = cookie();
        String request = """
            {"request":{"requestId":"version-test","expectedRevision":0,
            "selections":[{"sourceInstanceId":"r","ruleId":"rally","bindingId":"sheet"}]}}""";

        String browser = java.nio.file.Files.readString(Path.of("web", "src", "automation", "panel.ts"));
        assertTrue(browser.contains("export const AUTOMATION_COMPATIBILITY_VERSION = "
                + OnlineProtocol.AUTOMATION_COMPATIBILITY_VERSION + ";"),
                "The browser and host must use the same automation compatibility version.");

        for (String version : List.of("unknown", "0", "999", "invalid")) {
            String path = "unknown".equals(version) ? "/api/automation/auto" : "/api/automation/" + version + "/auto";
            URI uri = URI.create("http://localhost:" + port + path);
            for (boolean post : List.of(false, true)) {
                var builder = HttpRequest.newBuilder(uri).header("Cookie", cookie);
                if (post) builder.POST(HttpRequest.BodyPublishers.ofString(request));
                else builder.GET();
                var denied = http.send(builder.build(), HttpResponse.BodyHandlers.ofString());
                assertEquals(409, denied.statusCode(), denied.body());
                JsonNode error = MAPPER.readTree(denied.body());
                assertEquals("automationCompatibilityMismatch", error.path("code").asText());
                assertEquals(version, error.path("clientVersion").asText());
                assertEquals(OnlineProtocol.AUTOMATION_COMPATIBILITY_VERSION, error.path("hostVersion").asInt());
                assertTrue(error.path("error").asText().contains("client version " + version));
                assertTrue(error.path("error").asText().contains("host version " + OnlineProtocol.AUTOMATION_COMPATIBILITY_VERSION));
                assertEquals(saved, store.loadSheet(campaign.getId(), "auto"));
            }
        }
        var unauthenticated = http.send(HttpRequest.newBuilder(URI.create("http://localhost:" + port
                + "/api/automation/0/auto")).GET().build(), HttpResponse.BodyHandlers.ofString());
        assertEquals(401, unauthenticated.statusCode());
        assertEquals(200, automationHttp(cookie, "auto", null).statusCode());
        var applied = automationHttp(cookie, "auto", request);
        assertEquals(200, applied.statusCode(), applied.body());
        assertEquals(3, MAPPER.readTree(store.loadSheet(campaign.getId(), "auto")).at("/hope/on").asInt());
        assertEquals(applied.body(), automationHttp(cookie, "auto", request).body());
    }

    @Test
    void actionRollProfileCommitsTrustedSpellcastFactsAndRetriesOnce() throws Exception {
        automationCompendium();
        Path file = compendiumDir.resolve("classes.json");
        ObjectNode catalog = (ObjectNode) MAPPER.readTree(file.toFile());
        ObjectNode feature = (ObjectNode) catalog.at("/entries/0/features/2/automation");
        feature.set("profiles", MAPPER.readTree("""
                [{"id":"cast","label":"Cast","rollKind":"spellcast","trait":"spellcast",
                  "difficulty":13,"origin":"card:Example"}]"""));
        feature.set("rules", MAPPER.readTree("""
                [{"id":"focus","bindings":[{"id":"use","event":"roll.prepare","surface":"roll","mode":"option"}],
                  "when":{"eq":[{"read":"event.check.origin"},"card:Example"]},
                  "costs":[{"op":"resource.spend","pool":"actor.hope","amount":1}],
                  "do":[{"op":"roll.contribute","from":{"read":"event.roll"},
                    "contribution":{"id":"focus","kind":"flat","role":"modifier","label":"Focus","value":4},"as":"next"},
                    {"op":"roll.publish","roll":{"read":"result.next"}}],"ui":{"label":"Focus"}},
                 {"id":"after","bindings":[{"id":"auto","event":"roll.finished","surface":"roll","mode":"automatic"}],
                  "when":{"eq":[{"read":"event.check.outcome"},"success"]},
                  "do":[{"op":"track.mark","track":"actor.stress","amount":1}],"ui":{"label":"After"}},
                 {"id":"result","bindings":[{"id":"use","event":"roll.finished","surface":"roll","mode":"button"}],
                  "when":{"eq":[{"read":"event.check.origin"},"card:Example"]},
                  "do":[{"op":"resource.gain","pool":"actor.hope","amount":1}],"ui":{"label":"Result"}}]"""));
        java.nio.file.Files.writeString(file, catalog.toString());
        String id = campaign.getId();
        campaign.getActors().add(Campaign.Actor.builder().id("caster").name("Ada").ownerId(playerId()).build());
        store.saveSheet(id, "caster", """
                {"name":"Ada","hope":{"slots":6,"on":2},"stress":{"slots":6,"on":0},
                 "traits":[{"name":"Agility","mod":3,"spellcast":true}],
                 "features":[{"name":"Steady","instanceId":"s","automationSource":"classes:tester:features:steady"}]}""");
        String owner = cookie(), other = allyCookie("other");
        var description = automationHttp(owner, "caster", null);
        assertEquals(200, description.statusCode(), description.body());
        JsonNode profile = MAPPER.readTree(description.body()).requiredAt("/profiles/0");
        assertEquals("spellcast", profile.required("rollKind").textValue());
        assertEquals(List.of("focus"), profile.requiredAt("/options/spellcast").findValuesAsText("ruleId"));
        String request = """
                {"request":{"requestId":"cast","expectedRevision":0,
                 "selections":[{"sourceInstanceId":"s","ruleId":"focus","bindingId":"use"}],
                 "profileRoll":{"sourceInstanceId":"s","profileId":"cast","kind":"spellcast"}}}""";
        assertEquals(403, automationHttp(other, "caster", request).statusCode());
        assertEquals(400, automationHttp(owner, "caster", request.replace("\"kind\":\"spellcast\"", "\"kind\":\"attack\"")).statusCode());
        int history = store.historyTail(id, 100).size();
        diceSeed(0);
        var response = automationHttp(owner, "caster", request);
        assertEquals(200, response.statusCode(), response.body());
        JsonNode result = MAPPER.readTree(response.body());
        assertEquals(13, result.requiredAt("/event/check/total").intValue());
        assertEquals("success", result.requiredAt("/event/check/outcome").textValue());
        assertEquals("card:Example", result.requiredAt("/event/check/origin").textValue());
        assertEquals(List.of("result"), result.required("resultActions").findValuesAsText("ruleId"));
        JsonNode saved = MAPPER.readTree(store.loadSheet(id, "caster"));
        assertEquals(1, saved.requiredAt("/hope/on").intValue());
        assertEquals(1, saved.requiredAt("/stress/on").intValue());
        assertEquals(1, saved.requiredAt("/automationState/revision").intValue());
        assertEquals(history + 1, store.historyTail(id, 100).size());
        assertEquals(response.body(), automationHttp(owner, "caster", request).body());
        assertEquals(history + 1, store.historyTail(id, 100).size());
        var reopened = new CampaignStore(temp.resolve("campaigns"));
        assertEquals(saved, MAPPER.readTree(reopened.loadSheet(id, "caster")));
        assertEquals(409, automationHttp(owner, "caster", request.replace("\"cast\",\"expectedRevision\"", "\"again\",\"expectedRevision\"")).statusCode());
    }

    @Test
    void convertedWardenRollReportAndUsePersistAtomicallyAndReplay() throws Exception {
        automationCompendium();
        JsonNode classes = MAPPER.readTree(Path.of("dmmap-daggerheart", "classes.json").toFile());
        JsonNode feature = null;
        for (JsonNode entry : classes.path("entries")) for (JsonNode candidate : entry.path("features"))
            if ("Warden’s Protection".equals(candidate.path("name").asText())) feature = candidate;
        assertNotNull(feature);
        ObjectNode legacy = MAPPER.createObjectNode().put("format", "dmmap-daggerheart").put("version", 1)
                .put("category", "classes").put("label", "Fixture");
        legacy.putArray("entries").addObject().put("id", "warden").put("name", "Warden")
                .putArray("features").add(feature.deepCopy());
        var converted = dmmt.online.automation.LegacyCatalogConverter.convert(legacy.toString());
        assertEquals(1, converted.converted(), converted.diagnostics().toString());
        String catalog = converted.catalog().toString();
        String sourceId = dmmt.online.automation.RuleCatalog.compile(catalog,
                dmmt.online.automation.LegacyCatalogConverter.coreRecipes()).getFirst().id();
        java.nio.file.Files.writeString(compendiumDir.resolve("classes.json"), catalog);

        String campaignId = campaign.getId();
        campaign.getActors().add(Campaign.Actor.builder().id("warden").name("Warden").ownerId(playerId()).build());
        campaign.getActors().add(Campaign.Actor.builder().id("ally").name("Ally").ownerId(playerId()).build());
        ObjectNode sheet = MAPPER.createObjectNode().put("name", "Warden").put("level", 2);
        sheet.putObject("hope").put("slots", 6).put("on", 1);
        sheet.putArray("features").addObject().put("name", feature.path("name").asText())
                .put("automationSource", sourceId).put("instanceId", "f-warden");
        store.saveSheet(campaignId, "warden", sheet.toString());
        store.saveSheet(campaignId, "ally", "{\"name\":\"Ally\",\"hp\":{\"slots\":6,\"on\":3}}");
        String owner = cookie(), other = allyCookie("warden-viewer");
        String request = """
                {"request":{"requestId":"warden-use","expectedRevision":0,
                 "selections":[{"sourceInstanceId":"f-warden","ruleId":"use","bindingId":"sheet"}]}}""";
        long seed = seedFor(random -> random.nextInt(4) == 3);
        diceSeed(seed);
        int history = store.historyTail(campaignId, 100).size();
        assertEquals(403, automationHttp(other, "warden", request).statusCode());
        assertEquals(409, automationHttp(owner, "warden", request).statusCode());
        assertEquals(history, store.historyTail(campaignId, 100).size());
        assertEquals(1, MAPPER.readTree(store.loadSheet(campaignId, "warden")).at("/hope/on").asInt());

        sheet.withObject("/hope").put("on", 6);
        store.saveSheet(campaignId, "warden", sheet.toString());
        var applied = automationHttp(owner, "warden", request);
        assertEquals(200, applied.statusCode(), applied.body());
        JsonNode receipt = MAPPER.readTree(applied.body());
        assertEquals("Clear 2 HP on each of up to 4 allies within Close range.", receipt.at("/actions/0/report").asText());
        assertEquals(4, receipt.at("/actions/0/diceRolls/0/contributions/0/dice/0/face").asInt());
        assertEquals(4, MAPPER.readTree(store.loadSheet(campaignId, "warden")).at("/hope/on").asInt());
        assertEquals(3, MAPPER.readTree(store.loadSheet(campaignId, "ally")).at("/hp/on").asInt(),
                "The narrative report must not guess or mutate targets.");
        assertEquals(history + 1, store.historyTail(campaignId, 100).size());
        assertTrue(store.historyTail(campaignId, 100).getLast().path("text").asText().contains(receipt.at("/actions/0/report").asText()));
        assertEquals(applied.body(), automationHttp(owner, "warden", request).body());
        assertEquals(history + 1, store.historyTail(campaignId, 100).size());
        var second = automationHttp(owner, "warden", request.replace("warden-use", "warden-again")
                .replace("\"expectedRevision\":0", "\"expectedRevision\":1"));
        assertEquals(409, second.statusCode(), second.body());

        var reopened = new CampaignStore(temp.resolve("campaigns"));
        JsonNode saved = MAPPER.readTree(reopened.loadSheet(campaignId, "warden"));
        assertEquals(4, saved.at("/hope/on").asInt());
        assertEquals(1, saved.at("/automationState/sources/f-warden/usage/uses").asInt(), saved.toString());
        assertTrue(saved.at("/automationState/journal").toString().contains("up to 4 allies"), saved.toString());
    }

