    private void measurePersistedMixedWeaponDamage(boolean derived, boolean traitDependent) throws Exception {
        automationCompendium();
        Path file = compendiumDir.resolve("classes.json");
        ObjectNode catalog = (ObjectNode) MAPPER.readTree(file.toFile());
        ObjectNode automation = (ObjectNode) catalog.at("/entries/0/features/2/automation");
        automation.set("modifiers", MAPPER.readTree("""
            [{"stat":"roll.damage","value":2,"label":"Damage passive"},
             {"stat":"roll.damage","value":1,"label":"Conditional damage",
              "when":{"gt":[{"read":"actor.hope.value"},0]}}]"""));
        if (traitDependent) {
            automation.withArray("modifiers").addObject().put("stat", "trait.Finesse").put("value", 1);
            ObjectNode dependent = automation.withArray("modifiers").addObject().put("stat", "roll.damage").put("label", "Current Finesse");
            dependent.set("value", MAPPER.readTree("{\"read\":\"actor.stats.trait.Finesse\"}"));
        }
        ArrayNode rules = automation.withArray("rules");
        rules.removeAll();
        rules.add(MAPPER.readTree("""
            {"id":"boost","bindings":[{"id":"option","surface":"roll","event":"roll.prepare","mode":"option"}],
             "ui":{"label":"Boost"},"do":[
             {"op":"roll.contribute","from":{"read":"event.roll"},"as":"boosted",
              "contribution":{"id":"boost","kind":"flat","role":"damage","label":"Boost","value":1}},
             {"op":"roll.publish","roll":{"read":"result.boosted"}}]}"""));
        rules.add(MAPPER.readTree("""
            {"id":"edit","bindings":[{"id":"auto","surface":"roll","event":"roll.finished","mode":"automatic"}],
             "ui":{"label":"Edit"},"do":[
             {"op":"roll.selectDice","from":{"read":"event.roll"},
              "where":{"includes":[{"read":"event.roll.metadata.weaponBaseContributions"},{"read":"die.contributionId"}]},"as":"selected"},
             {"op":"roll.addDicePerPool","from":{"read":"event.roll"},"dice":{"read":"result.selected"},"count":1,"as":"added"},
             {"op":"roll.selectDice","from":{"read":"result.added"},
              "where":{"includes":[{"read":"event.roll.metadata.weaponBaseContributions"},{"read":"die.contributionId"}]},"as":"all"},
             {"op":"roll.dropLowestPerPool","from":{"read":"result.added"},"dice":{"read":"result.all"},"count":1,"as":"dropped"},
             {"op":"roll.publish","roll":{"read":"result.dropped"}}]}"""));
        if (derived) {
            ObjectNode effect = automation.putObject("effects").putObject("form").put("label", "Form");
            effect.set("while", MAPPER.readTree("{\"gt\":[{\"read\":\"actor.hope.value\"},0]}"));
            effect.set("profile", MAPPER.readTree("{\"label\":\"Claws\",\"trait\":\"Finesse\",\"damage\":{\"sides\":8}}"));
            rules.add(MAPPER.readTree("""
               {"id":"after","bindings":[{"id":"use","event":"roll.finished","surface":"roll","mode":"button"}],
                "ui":{"label":"After"},"do":[{"op":"resource.gain","pool":"actor.hope","amount":1}]}"""));
        }
        java.nio.file.Files.writeString(file, catalog.toString());
        campaign.getActors().add(Campaign.Actor.builder().id("roller").name("Ada").ownerId(playerId()).build());
        ObjectNode sheet = performanceSheet().put("name", "Ada").put("notes", "Session notes. ".repeat(800));
        sheet.putObject("proficiency").put("on", 2).put("slots", 6);
        sheet.putArray("traits").addObject().put("name", "Finesse").put("mod", 3);
        sheet.putArray("features");
        sheet.putArray("activeWeapons").addObject().put("name", "Mixed Blade").put("slot", "Primary")
                .put("trait", "Finesse").put("range", "Melee").put("damage", "d8+d6+2").put("damageType", "phys")
                .put("instanceId", "steady").put("automationSource", "classes:tester:features:steady");
        sheet.putObject("automationState").putArray("effects").addObject()
                .put("id", "active-bonus").put("sourceInstanceId", "steady").put("label", "Stored effect")
                .putArray("modifiers").addObject().put("stat", "roll.damage").put("value", 3);
        store.saveSheet(campaign.getId(), "roller", sheet.toString());
        String cookie = cookie();
        var alloc = java.lang.management.ManagementFactory.getPlatformMXBean(com.sun.management.ThreadMXBean.class);
        if (alloc == null || !alloc.isThreadAllocatedMemorySupported())
            throw new IllegalStateException("The benchmark requires JVM allocation counters.");
        alloc.setThreadAllocatedMemoryEnabled(true);
        int warmup = 20, samples = 40;
        long[] nanos = new long[samples], bytes = new long[samples];
        for (int i = 0; i < warmup + samples; i++) {
            String body = """
                {"request":{"requestId":"mixed-%d","expectedRevision":%d,"selections":[
                 {"sourceInstanceId":"steady","ruleId":"boost","bindingId":"option"}],
                 "profileRoll":{"sourceInstanceId":"steady","profileId":"weapon.base","kind":"damage"}}}"""
                    .formatted(i, i);
            long allocated = alloc.getTotalThreadAllocatedBytes(), start = System.nanoTime();
            var response = automationHttp(cookie, "roller", body);
            long elapsed = System.nanoTime() - start, used = alloc.getTotalThreadAllocatedBytes() - allocated;
            assertEquals(200, response.statusCode(), response.body());
            JsonNode result = MAPPER.readTree(response.body());
            assertEquals(i + 1, result.required("revision").intValue());
            if (derived) assertTrue(result.requiredAt("/event/resultId").isTextual());
            JsonNode roll = result.requiredAt("/event/roll");
            assertEquals("[\"damage\",\"damage.2\"]", roll.requiredAt("/metadata/weaponBaseContributions").toString());
            assertEquals(3, roll.requiredAt("/contributions/0/dice").size());
            assertEquals(3, roll.requiredAt("/contributions/1/dice").size());
            assertEquals(8, roll.requiredAt("/contributions/0/dice/2/sides").intValue());
            assertEquals(6, roll.requiredAt("/contributions/1/dice/2/sides").intValue());
            assertEquals(2, roll.required("excludedDice").size());
            assertTrue(roll.required("contributions").findValuesAsText("label")
                    .containsAll(List.of("Damage passive", "Conditional damage", "Stored effect", "Boost")));
            if (traitDependent)
                assertTrue(roll.required("contributions").findValuesAsText("label").contains("Current Finesse"));
            assertEquals(roll.requiredAt("/contributions/0/total").intValue()
                            + roll.requiredAt("/contributions/1/total").intValue() + (traitDependent ? 13 : 9),
                    roll.required("total").intValue());
            if (i >= warmup) {
                nanos[i - warmup] = elapsed;
                bytes[i - warmup] = used;
            }
        }
        assertEquals(warmup + samples,
                MAPPER.readTree(store.loadSheet(campaign.getId(), "roller")).requiredAt("/automationState/revision").intValue());
        java.util.Arrays.sort(nanos);
        System.out.printf(java.util.Locale.ROOT, "automation-bench %s POST: n=%d p50=%.2fms p95=%.2fms mean=%.2fMiB allocated%n",
                derived ? "mixed weapon with derived activation" : traitDependent ? "mixed weapon with trait-dependent passive" : "mixed weapon", samples,
                nanos[samples / 2 - 1] / 1e6, nanos[(int) Math.ceil(samples * .95) - 1] / 1e6,
                java.util.Arrays.stream(bytes).average().orElseThrow() / (1024 * 1024));
    }

    @Test
    void partyActionRefreshesOnMembershipOrSheetChangesAndCommitsOnlyOnce() throws Exception {
        ObjectNode catalog = installPartyAction();
        Path file = compendiumDir.resolve("classes.json");
        ObjectNode automation = (ObjectNode) catalog.at("/entries/0/features/0/automation");
        var selector = (ObjectNode) automation.at("/rules/0/bindings/0/targetSelection");
        selector.put("scope", "activePlayerCharacters");
        selector.set("where", MAPPER.readTree("{\"gt\":[{\"read\":\"recipient.stress.marked\"},0]}"));
        var steps = (ArrayNode) automation.at("/rules/0/do");
        steps.addObject().put("op", "table.spend").put("resource", "fear").put("amount", 1).put("label", "Fear");
        java.nio.file.Files.writeString(file, catalog.toString());
        String cookie = cookie(), id = campaign.getId();
        String other = allyCookie("other");
        String allySheet = "{\"name\":\"Ally\",\"stress\":{\"on\":2,\"slots\":6}}";
        for (String name : List.of("caster", "ally", "late", "rested", "disabled", "unowned", "unsaved")) {
            campaign.getActors().add(Campaign.Actor.builder().id(name).name(name)
                    .ownerId(name.equals("caster") ? playerId() : name.equals("unowned") ? null : "other")
                    .disabled(name.equals("disabled") || name.equals("late")).build());
            if (!name.equals("unsaved")) store.saveSheet(id, name, name.equals("rested") ? allySheet.replace("\"on\":2", "\"on\":0") : allySheet);
        }
        store.saveSheet(id, "caster", """
            {"name":"Ada","hope":{"slots":6,"on":2},"stress":{"slots":6,"on":2},"features":[
             {"name":"Rally","automationSource":"classes:tester:features:rally","instanceId":"r"}]}""");
        String original = store.loadSheet(id, "caster");
        var described = automationHttp(cookie, "caster", null);
        assertEquals(200, described.statusCode(), described.body());
        assertEquals(3, server.sheetDiagnostics().hydrations(), "Eligibility must inspect every scoped saved recipient.");
        JsonNode offer = MAPPER.readTree(described.body()).at("/actions/0/targetSelection");
        assertEquals(List.of("ally"), offer.path("options").findValuesAsText("id"));
        assertFalse(offer.toString().contains("snapshot"));
        ObjectNode body = MAPPER.createObjectNode();
        ObjectNode request = body.putObject("request").put("requestId", "cast").put("expectedRevision", 0);
        request.putArray("selections").addObject().put("sourceInstanceId", "r").put("ruleId", "rally").put("bindingId", "sheet");
        ObjectNode target = request.putObject("target");
        target.set("version", offer.required("version"));
        assertEquals(403, automationHttp(other, "caster", body.toString()).statusCode());
        target.put("recipientId", "ally");
        assertEquals(400, automationHttp(cookie, "caster", body.toString()).statusCode());
        target.remove("recipientId");
        campaign.actor("late").setDisabled(false);
        assertEquals(409, automationHttp(cookie, "caster", body.toString()).statusCode());
        var updated = MAPPER.readTree(automationHttp(cookie, "caster", null).body()).at("/actions/0/targetSelection");
        assertEquals(List.of("ally", "late"), updated.path("options").findValuesAsText("id"));
        target.set("version", updated.required("version"));
        var edit = (ObjectNode) MAPPER.readTree(store.loadSheet(id, "late"));
        store.saveSheet(id, "late", edit.put("notes", "ordinary edit").toString());
        assertEquals(409, automationHttp(cookie, "caster", body.toString()).statusCode());
        target.set("version", MAPPER.readTree(automationHttp(cookie, "caster", null).body()).at("/actions/0/targetSelection/version"));
        campaign.setFear(1); // second recipient cannot pay
        int history = store.historyTail(id, 100).size();
        var insufficientFear = automationHttp(cookie, "caster", body.toString());
        assertEquals(409, insufficientFear.statusCode(), insufficientFear.body());
        assertTrue(insufficientFear.body().contains("Not enough GM Fear"));
        assertEquals(1, campaign.getFear());
        assertEquals(original, store.loadSheet(id, "caster"));
        assertEquals(2, MAPPER.readTree(store.loadSheet(id, "ally")).at("/stress/on").asInt());
        assertEquals(history, store.historyTail(id, 100).size());
        campaign.setFear(2);
        var applied = automationHttp(cookie, "caster", body.toString());
        assertEquals(200, applied.statusCode(), applied.body());
        assertEquals(4, server.sheetDiagnostics().hydrations(), "Filtered fanout must inspect even an ineligible recipient.");
        assertEquals(List.of("ally", "late"), MAPPER.readTree(applied.body()).path("actions").findValuesAsText("recipientId"));
        assertEquals(0, campaign.getFear());
        assertEquals(1, MAPPER.readTree(store.loadSheet(id, "caster")).at("/hope/on").asInt());
        for (String actor : List.of("ally", "late")) {
            var saved = MAPPER.readTree(store.loadSheet(id, actor));
            assertEquals(1, saved.at("/automationState/revision").asInt());
            assertEquals(1, saved.at("/stress/on").asInt());
            assertEquals(1, saved.at("/automationState/pools/favor/value").asInt());
        }
        campaign.actor("late").setDisabled(true);
        assertEquals(applied.body(), automationHttp(cookie, "caster", body.toString()).body());
        assertEquals(history + 2, store.historyTail(id, 100).size());
    }

